     */
    public int largestIsland(int[][] grid) {
        int n = grid.length;
        int islandId = 2; // Start island ID from 2 to avoid conflict with 0 and 1
        HashMap<Integer, Integer> islandSizes = new HashMap<>();
        int maxIslandSize = 0;

        // Step 1: Find all islands and calculate their sizes
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
