        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    HashSet<Integer> adjacentIslands = new HashSet<>();
                    if (i > 0 && grid[i - 1][j] == 1) {
                        adjacentIslands.add(getIslandId(grid, i - 1, j));
