public class Solution {
    public int largestIsland(int[][] grid) {
        int n = grid.length;
        int islandId = 2;
        int maxArea = 0;
        HashMap<Integer, Integer> islandSizes = new HashMap<>();

        // DFS to find and label islands
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int area = dfs(grid, i, j, islandId);
                    islandSizes.put(islandId, area);
                    maxArea = Math.max(maxArea, area);
                    islandId++;
                }
            }
        }

        // Check for 0s and calculate connected island size
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    HashSet<Integer> connectedIslands = new HashSet<>();
                    int area = 1;

                    // Check neighbors
                    int[] dx = {0, 0, 1, -1};
                    int[] dy = {1, -1, 0, 0};

                    for (int k = 0; k < 4; k++) {
                        int x = i + dx[k];
                        int y = j + dy[k];

                        if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] != 0) {
                            int island = grid[x][y];
                            if (!connectedIslands.contains(island)) {
                                area += islandSizes.get(island);
                                connectedIslands.add(island);
                            }
                        }
                    }
                    maxArea = Math.max(maxArea, area);
                }
            }
        }

        return maxArea;
    }

    private int dfs(int[][] grid, int i, int j, int islandId) {
        int n = grid.length;
        if (i < 0 || i >= n || j < 0 || j >= n || grid[i][j] != 1) {
            return 0;
        }

        grid[i][j] = islandId;
        int area = 1;

        area += dfs(grid, i + 1, j, islandId);
        area += dfs(grid, i - 1, j, islandId);
        area += dfs(grid, i, j + 1, islandId);
        area += dfs(grid, i, j - 1, islandId);

        return area;
    }
}

