public class Solution {
    public int numMagicSquaresInside(int[][] grid) {
        if (grid == null || grid.length < 3 || grid[0].length < 3) {
            return 0;
        }

        int rows = grid.length;
        int cols = grid[0].length;
        int count = 0;

        for (int i = 0; i <= rows - 3; i++) {
            for (int j = 0; j <= cols - 3; j++) {
                if (isMagicSquare(grid, i, j)) {
                    count++;
                }
            }
        }

        return count;
    }

    private boolean isMagicSquare(int[][] grid, int rowStart, int colStart) {
        int sum = 0;
        for (int i = 0; i < 3; i++) {
            sum += grid[rowStart + i][colStart + i];
        }

        // Check rows
        for (int i = 0; i < 3; i++) {
            int rowSum = 0;
            for (int j = 0; j < 3; j++) {
                rowSum += grid[rowStart + i][colStart + j];
            }
            if (rowSum != sum) {
                return false;
            }
        }

        // Check columns
        for (int j = 0; j < 3; j++) {
            int colSum = 0;
            for (int i = 0; i < 3; i++) {
                colSum += grid[rowStart + i][colStart + j];
            }
            if (colSum != sum) {
                return false;
            }
        }

        // Check main diagonal
        int mainDiagonalSum = 0;
        for (int i = 0; i < 3; i++) {
            mainDiagonalSum += grid[rowStart + i][colStart + i];
        }
        if (mainDiagonalSum != sum) {
            return false;
        }

        // Check anti-diagonal
        int antiDiagonalSum = 0;
        for (int i = 0; i < 3; i++) {
            antiDiagonalSum += grid[rowStart + i][colStart + 2 - i];
        }
        if (antiDiagonalSum != sum) {
            return false;
        }

        // Check for distinct numbers from 1 to 9
        Set<Integer> numbers = new HashSet<>();
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                int num = grid[rowStart + i][colStart + j];
                if (num < 1 || num > 9 || !numbers.add(num)) {
                    return false;
                }
            }
        }

        return true;
    }

    private int rowStart;
    private int colStart;
}

