import java.util.HashMap;
import java.util.Map;
import java.util.TreeSet;

public class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        int x = 0, y = 0;
        int dir = 1; // 1: North, 2: East, 3: South, 4: West
        int maxDistSq = 0;

        TreeSet<Integer> obstacleSetX = new TreeSet<>();
        TreeSet<Integer> obstacleSetY = new TreeSet<>();
        for (int[] obstacle : obstacles) {
            obstacleSetX.add(obstacle[0]);
            obstacleSetY.add(obstacle[1]);
        }

        for (int command : commands) {
            if (command < 0) {
                dir = (dir + 1) % 4;
            } else if (command > 0) {
                int dx = 0, dy = 0;
                if (dir == 1) { // North
                    dy = command;
                } else if (dir == 2) { // East
                    dx = command;
                } else if (dir == 3) { // South
                    dy = -command;
                } else { // West
                    dx = -command;
                }

                int nextX = x + dx;
                int nextY = y + dy;

                while (x != nextX || y != nextY) {
                    if (x != nextX) {
                        int stepX = (nextX > x) ? 1 : -1;
                        int tempX = x + stepX;
                        if (obstacleSetX.contains(tempX)) {
                            break;
                        }
                        x = tempX;
                    } else {
                        int stepY = (nextY > y) ? 1 : -1;
                        int tempY = y + stepY;
                        if (obstacleSetY.contains(tempY)) {
                            break;
                        }
                        y = tempY;
                    }
                }

                maxDistSq = Math.max(maxDistSq, x * x + y * y);
            }
        }

        return maxDistSq;
    }
}

