public class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        int x = 0;
        int y = 0;
        int direction = 1; // 1: North, 2: East, 3: South, 4: West
        int maxDistSq = 0;

        TreeSet<Integer> obstacleSetX = new TreeSet<>();
        TreeSet<Integer> obstacleSetY = new TreeSet<>();
        for (int[] obstacle : obstacles) {
            obstacleSetX.add(obstacle[0]);
            obstacleSetY.add(obstacle[1]);
        }


        for (int command : commands) {
            if (command < 0) {
                direction = (direction + 3) % 4 + 1;
            } else if (command > 0) {
                int dx = 0;
                int dy = 0;

                if (direction == 1) { // North
                    dy = command;
                } else if (direction == 2) { // East
                    dx = command;
                } else if (direction == 3) { // South
                    dy = -command;
                } else { // West
                    dx = -command;
                }

                int nextX = x + dx;
                int nextY = y + dy;

                boolean obstacleEncountered = false;
                for (int i = 0; i < command; i++) {
                    int tempX = x + dx * (i + 1);
                    int tempY = y + dy * (i + 1);
                    if (obstacleSetX.contains(tempX) && obstacleSetY.contains(tempY)) {
                        obstacleEncountered = true;
                        break;
                    }
                }

                if (!obstacleEncountered) {
                    x += dx;
                    y += dy;
                }


                maxDistSq = Math.max(maxDistSq, x * x + y * y);
            }
        }

        return maxDistSq;
    }
}

