public class Solution {
    public int nthMagicalNumber(int n, int a, int b) {
        long MOD = 1000000007;
        long low = Math.min(a, b);
        long high = (long)n * Math.min(a, b);

        while (low < high) {
            long mid = low + (high - low) / 2;
            long count = mid / a + mid / b - mid / (long)lcm(a, b);
            if (count < n) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }

        return (int)(low % MOD);
    }

