public class Solution {
    public int profitableSchemes(int n, int minProfit, int[] group, int[] profit) {
        int MOD = 1000000007;
        int m = group.length;

        // dp[i][j][k] represents the number of schemes using the first i crimes
        // with total profit at least j and total members at most k.
        int[][][] dp = new int[m + 1][minProfit + 1][n + 1];

        // Base case: No crimes, profit is 0, and no members are used.
        dp[0][0][0] = 1;

        for (int i = 1; i <= m; i++) {
            for (int j = 0; j <= minProfit; j++) {
                for (int k = 0; k <= n; k++) {
                    // Option 1: Don't include the i-th crime.
                    dp[i][j][k] = dp[i - 1][j][k];

                    // Option 2: Include the i-th crime if possible.
                    if (group[i - 1] <= k) {
                        int prevProfit = Math.max(0, j - profit[i - 1]);
                        dp[i][j][k] = (dp[i][j][k] + dp[i - 1][prevProfit][k - group[i - 1]]) % MOD;
                    }
                }
            }
        }

        int totalSchemes = 0;
        for (int j = minProfit; j <= minProfit; j++) {
            for (int k = 0; k <= n; k++) {
                totalSchemes = (totalSchemes + dp[m][j][k]) % MOD;
            }
        }

        for (int j = minProfit; j <= m; j++) {
            for (int k = 0; k <= n; k++) {
                totalSchemes = (totalSchemes + dp[m][j][k]) % MOD;
            }
        }

        int ans = 0;
        for (int j = minProfit; j <= m; j++) {
            for (int k = 0; k <= n; k++) {
                ans = (ans + dp[m][j][k]) % MOD;
            }
        }

        return ans;
    }
