    public double soupServings(int n) {
        if (n <= 0) {
            return 1.0;
        }

        double[][] dp = new double[n + 1][n + 1];

        // Initialize base case: when both types of soup are empty
        dp[0][0] = 1.0;

        // Iterate over all possible remaining volumes of soup A and B
        for (int a = 0; a <= n; a++) {
            for (int b = 0; b <= n; b++) {
                // If we have already reached a state where one of the soups is empty,
                // we cannot serve any more soup.
                if (a == 0 && b == 0) {
                    continue;
                }

                // Serve 100 ml of soup A and 0 ml of soup B
                if (a >= 100) {
                    dp[a - 100][b] += dp[a][b];
                }
                // Serve 75 ml of soup A and 25 ml of soup B
                if (a >= 75 && b >= 25) {
                    dp[a - 75][b - 25] += dp[a][b];
                }
                // Serve 50 ml of soup A and 50 ml of soup B
                if (a >= 50 && b >= 50) {
                    dp[a - 50][b - 50] += dp[a][b];
                }
                // Serve 25 ml of soup A and 75 ml of soup B
                if (a >= 25 && b >= 75) {
                    dp[a - 25][b - 75] += dp[a][b];
                }
            }
        }

        double probAEmptyFirst = 0.0;
        for (int i = 0; i <= n; i++) {
            probAEmptyFirst += dp[i][0];
        }

        double probBothEmpty = dp[0][0];

        return probAEmptyFirst + 0.5 * probBothEmpty;
    }
}

