public class Solution {
    public double new21Game(int n, int k, int w) {
        if (k <= n) {
            return 1.0;
        }

        double[] dp = new double[n + 1];
        dp[0] = 1.0;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= w && j <= i; j++) {
                dp[i] += dp[i - j] * (1.0 / w);
            }
        }

        return dp[n];
    }
}

