import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        s = s.substring(1, s.length() - 1);
        helper(s, 0, new ArrayList<>(), result);
        return result;
    }

    private void helper(String s, int index, List<String> current, List<String> result) {
        if (index == s.length()) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < current.size(); i++) {
                sb.append(current.get(i));
                if (i < current.size() - 1) {
                    sb.append(", ");
                }
            }
            result.add(sb.toString());
            return;
        }

        for (int i = index; i < s.length(); i++) {
            String num = s.substring(index, i + 1);
            if (isValid(num)) {
                List<String> next = new ArrayList<>(current);
                next.add(num);
                helper(s, i + 1, next, result);
            }
        }
    }

    private boolean isValid(String s) {
        if (s.isEmpty()) {
            return false;
        }

        if (s.length() > 1 && s.startsWith("0") && s.contains(".")) {
            return false;
        }

        if (s.length() > 1 && s.startsWith("0") && !s.contains(".")) {
            return false;
        }

        if (s.contains(".")) {
            int dotIndex = s.indexOf('.');
            if (dotIndex == 0 || dotIndex == s.length() - 1) {
                return false;
            }
            String beforeDot = s.substring(0, dotIndex);
            String afterDot = s.substring(dotIndex + 1);
            if (beforeDot.isEmpty() || afterDot.isEmpty()) {
                return false;
            }
        }

        try {
            Double.parseDouble(s);
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }
}

