import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        if (s == null || s.length() == 0) {
            return result;
        }

        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                for (int j = i + 1; j < s.length(); j++) {
                    if (s.charAt(j) == ',') {
                        for (int k = j + 1; k < s.length(); k++) {
                            if (s.charAt(k) == ')') {
                                String xStr = s.substring(i + 1, j);
                                String yStr = s.substring(j + 1, k);
                                String x = interpretNumber(xStr);
                                String y = interpretNumber(yStr);

                                if (x != null && y != null) {
                                    result.add("(" + x + ", " + y + ")");
                                }
                            }
                        }
                    }
                }
            }
        }

        return result;
    }

    private String interpretNumber(String s) {
        if (s.length() == 0) {
            return null;
        }

        if (s.startsWith("0") && s.length() > 1) {
            return null;
        }

        if (s.contains(".")) {
            int dotIndex = s.indexOf(".");
            if (dotIndex == 0) {
                return null;
            }

            String integerPart = s.substring(0, dotIndex);
            String fractionalPart = s.substring(dotIndex + 1);

            if (integerPart.length() == 0 && fractionalPart.length() == 0) {
                return null;
            }

            if (integerPart.length() > 0 && integerPart.startsWith("0") && integerPart.length() > 1) {
                return null;
            }
            if (fractionalPart.length() > 0 && fractionalPart.startsWith("0")) {
                return null;
            }
            return String.valueOf(Double.parseDouble(s));
        } else {
            if (s.startsWith("0") && s.length() > 1) {
                return null;
            }
            return s;
        }
    }
}

