                if (grid[i][j] == 1) {
                    if (isStable(grid, i, j)) {
                        stableCount++;
                    }
                }
            }
        }

        // Apply hits and calculate falling bricks
        for (int i = 0; i < hits.length; i++) {
            int row = hits[i][0];
            int col = hits[i][1];

            if (grid[row][col] == -1) {
                grid[row][col] = 1;
                int falling = 0;
                if (isStable(grid, row, col)) {
                    falling = countFalling(grid, row, col);
                }
                result[i] = falling;
            } else {
                result[i] = 0;
            }
        }

        return result;
    }

    private boolean isStable(int[][] grid, int row, int col) {
        int m = grid.length;
        int n = grid[0].length;

        if (row == 0) {
            return true;
        }

        if (grid[row][col] == 0) {
            return false;
        }

        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] dir : directions) {
            int newRow = row + dir[0];
            int newCol = col + dir[1];
            if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n && grid[newRow][newCol] == 1) {
                return true;
            }
        }

        return false;
    }

    private int countFalling(int[][] grid, int row, int col) {
        int m = grid.length;
        int n = grid[0].length;
        int count = 0;

        if (grid[row][col] == 0 || grid[row][col] == -1) {
            return 0;
        }

        grid[row][col] = -1;
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

