            int newCol = col + dir[1];

            if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n && grid[newRow][newCol] == 1) {
                if (!isStable(grid, newRow, newCol)) {
                    count += countFalling(grid, newRow, newCol);
                }
            }
        }

        return count + 1;
    }
