public class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int[] result = new int[hits.length];

        // Mark hits as -1 to avoid them being processed as bricks
        for (int[] hit : hits) {
            int row = hit[0];
            int col = hit[1];
            if (grid[row][col] == 1) {
                grid[row][col] = -1;
            }
        }

        // Find stable bricks and count them
        int stableBricks = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    if (isStable(grid, i, j)) {
                        stableBricks++;
                    }
                }
            }
        }

        // Process hits and update result
        for (int i = 0; i < hits.length; i++) {
            int row = hits[i][0];
            int col = hits[i][1];

            if (grid[row][col] == -1) {
                grid[row][col] = 1;
                int bricksFallen = 0;

                // Check if the hit brick was stable and caused other bricks to fall
                if (isStable(grid, row, col)) {
                    bricksFallen = countFallingBricks(grid, row, col);
                }

                result[i] = bricksFallen;
            } else {
                result[i] = 0;
            }
        }

        return result;
    }

    private boolean isStable(int[][] grid, int row, int col) {
        int m = grid.length;
        int n = grid[0].length;

        if (row == 0) {
            return true;
        }

        if (grid[row][col] == 0) {
            return false;
        }

        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] dir : directions) {
            int newRow = row + dir[0];
            int newCol = col + dir[1];
            if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n && grid[newRow][newCol] == 1) {
                return true;
            }
        }

        return false;
    }

    private int countFallingBricks(int[][] grid, int row, int col) {
        int m = grid.length;
        int n = grid[0].length;
        int count = 0;

        if (grid[row][col] == -1 || !isStable(grid, row, col)) {
            return 0;
        }

        boolean[][] visited = new boolean[m][n];

        count = dfs(grid, row, col, visited);

        return count;
    }

    private int dfs(int[][] grid, int row, int col, boolean[][] visited) {
        int m = grid.length;
        int n = grid[0].length;

        if (row < 0 || row >= m || col < 0 || col >= n || grid[row][col] != 1 || visited[row][col]) {
            return 0;
        }

        visited[row][col] = true;

        int count = 1;

        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] dir : directions) {
            int newRow = row + dir[0];
            int newCol = col + dir[1];
            if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n && grid[newRow][newCol] == 1) {
                count += dfs(grid, newRow, newCol, visited);
            }
        }

        return count;
    }
}

