        for (int i = 0; i < indices.length; i++) {
            int index = indices[i];
            String source = sources[i];
            String target = targets[i];
            if (s.substring(index).startsWith(source)) {
                replacements.put(index, new Replacement(source, target));
            }
        }

        StringBuilder result = new StringBuilder();
        int currentIndex = 0;
        for (int i = 0; i < s.length(); i++) {
            if (replacements.containsKey(currentIndex)) {
                Replacement replacement = replacements.get(currentIndex);
                result.append(s.substring(i, i + replacement.source.length()));
                i += replacement.source.length() - 1;
                result.append(replacement.target);
                currentIndex += replacement.source.length();
            } else {
                result.append(s.charAt(i));
            }
        }

        return result.toString();
    }

    private static class Replacement {
        String source;
        String target;

        public Replacement(String source, String target) {
            this.source = source;
            this.target = target;
        }
    }
}

