public class Solution {
    public int surfaceArea(int[][] grid) {
        int n = grid.length;
        int surfaceArea = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > 0) {
                    surfaceArea += 2; // Top and bottom faces

                    // Calculate surface area based on adjacent cells
                    int height = grid[i][j];

                    // Check adjacent cells and subtract overlapping areas
                    if (i > 0 && grid[i - 1][j] > 0) {
                        height -= Math.min(height, grid[i - 1][j]);
                    }
                    if (i < n - 1 && grid[i + 1][j] > 0) {
                        height -= Math.min(height, grid[i + 1][j]);
                    }
                    if (j > 0 && grid[i][j - 1] > 0) {
                        height -= Math.min(height, grid[i][j - 1]);
                    }
                    if (j < n - 1 && grid[i][j + 1] > 0) {
                        height -= Math.min(height, grid[i][j + 1]);
                    }

                    surfaceArea += height * 2;
                }
            }
        }

        return surfaceArea;
    }
}

