public class Solution {
    public int subarrayBitwiseORs(int[] arr) {
        Set<Integer> results = new HashSet<>();
        for (int i = 0; i < arr.length; i++) {
            int currentOr = 0;
            for (int j = i; j < arr.length; j++) {
                currentOr |= arr[j];
                results.add(currentOr);
            }
        }
        return results.size();
    }
}

