// #Hard #Array #Dynamic_Programming #Greedy #Heap_Priority_Queue
// #2022_03_28_Time_3_ms_(88.52%)_Space_48.8_MB_(60.04%)
import java.util.PriorityQueue;

public class Solution {
    public int minRefuelStops(int target, int startFuel, int[][] stations) {
        int stops = 0;
        int currentFuel = startFuel;
        int currentPosition = 0;
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);

        int i = 0;
        while (currentPosition < target) {
            // Add gas stations that can be reached to the priority queue
            while (i < stations.length && stations[i][0] <= currentPosition + currentFuel) {
                pq.offer(stations[i][1]);
                i++;
            }

            // If no gas stations can be reached, it's impossible to reach the target
            if (pq.isEmpty()) {
                return -1;
            }

            // Refuel at the gas station with the most fuel
            currentFuel -= (stations.length > 0 ? (i > 0 ? stations[i-1][0] - currentPosition : 0) : 0);
            currentFuel += pq.poll();
            currentPosition += (stations.length > 0 ? (i > 0 ? stations[i-1][0] - currentPosition : 0) : 0);
            stops++;
        }

        return stops;
    }
}

