import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int maxProfitAssignment(int[] difficulty, int[] profit, int[] worker) {
        int n = difficulty.length;
        int m = worker.length;

        Job[] jobs = new Job[n];
        for (int i = 0; i < n; i++) {
            jobs[i] = new Job(difficulty[i], profit[i]);
        }

        Arrays.sort(jobs, Comparator.comparingInt(j -> j.difficulty));

        Arrays.sort(worker);

        int totalProfit = 0;
        int jobIndex = 0;
        int workerIndex = 0;
        int bestProfit = 0;

        while (workerIndex < m) {
            if (jobIndex < n && jobs[jobIndex].difficulty <= worker[workerIndex]) {
                bestProfit = Math.max(bestProfit, jobs[jobIndex].profit);
                totalProfit += bestProfit;
                workerIndex++;
                jobIndex++;
            } else {
                workerIndex++;
            }
        }

        return totalProfit;
    }

    private static class Job {
        int difficulty;
        int profit;

        public Job(int difficulty, int profit) {
            this.difficulty = difficulty;
            this.profit = profit;
        }
    }
}

