public class Solution {
    public boolean lemonadeChange(int[] bills) {
        int five = 0;
        int ten = 0;

        for (int bill : bills) {
            if (bill == 5) {
                five++;
            } else if (bill == 10) {
                if (five == 0) {
                    return false;
                }
                five--;
                ten++;
            } else { // bill == 20
                if (ten == 0) {
                    if (five == 0) {
                        return false;
                    }
                    five--;
                } else {
                    ten--;
                    five--;
                }
            }
        }

        return true;
    }
}

