import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

public class Solution {
    public boolean reorderedPowerOf2(int n) {
        Map<Integer, Integer> digitCounts = new HashMap<>();
        for (char c : String.valueOf(n).toCharArray()) {
            digitCounts.put(c - '0', digitCounts.getOrDefault(c - '0', 0) + 1);
        }

        for (int i = 0; i < 31; i++) {
            int powerOf2 = 1 << i;
            Map<Integer, Integer> powerDigitCounts = new HashMap<>();
            for (char c : String.valueOf(powerOf2).toCharArray()) {
                powerDigitCounts.put(c - '0', powerDigitCounts.getOrDefault(c - '0', 0) + 1);
            }

            if (digitCounts.equals(powerDigitCounts)) {
                return true;
            }
        }

        return false;
    }
}

