public class Solution {
    public int smallestPrimePalindrome(int n) {
        if (n == 2) {
            return 2;
        }

        if (n <= 10) {
            if (n == 2) return 2;
            if (n == 1) return 2;
            if (n == 11) return 11;
            if (n == 10) return 11;
            if (n == 1) return 2;
            if (n == 3) return 3;
            if (n == 5) return 5;
            if (n == 7) return 7;
            if (n == 9) return 11;
        }

        String s = String.valueOf(n);
        int len = s.length();

        while (true) {
            String palindrome = generatePalindrome(s);
            int num = Integer.parseInt(palindrome);

            if (num >= n && isPrime(num)) {
                return num;
            }

            String nextS = incrementString(s);
            s = nextS;
        }
    }

    private String generatePalindrome(String s) {
        int len = s.length();
        String firstHalf = s;
        if (len % 2 == 0) {
            firstHalf = s.substring(0, len / 2);
        } else {
            firstHalf = s.substring(0, (len + 1) / 2);
        }

        String secondHalf = new StringBuilder(firstHalf).reverse().toString();

        if (len % 2 == 0) {
            return firstHalf + secondHalf;
        } else {
            return firstHalf + secondHalf.substring(1);
        }
    }

    private String incrementString(String s) {
        int len = s.length();
        int carry = 1;
        char[] chars = s.toCharArray();

        for (int i = len - 1; i >= 0; i--) {
            int digit = chars[i] - '0';
            int sum = digit + carry;
            chars[i] = (char) ((sum % 10) + '0');
            carry = sum / 10;
            if (carry == 0) {
                break;
            }
        }

        if (carry > 0) {
            return String.valueOf(carry) + new String(chars);
        } else {
            return new String(chars);
        }
    }

    private boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

