public class Solution {
    public int minEatingSpeed(int[] piles, int h) {
        int left = 1;
        int right = 0;
        for (int pile : piles) {
            right = Math.max(right, pile);
        }

        int minSpeed = right;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            long hoursNeeded = 0;
            for (int pile : piles) {
                hoursNeeded += (double) pile / mid;
            }

            if (hoursNeeded <= h) {
                minSpeed = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        return minSpeed;
    }
}

