public class Solution {
    public int numSpecialEquivGroups(String[] words) {
        HashSet<String> seen = new HashSet<>();
        int count = 0;

        for (String word : words) {
            String key = generateKey(word);
            if (!seen.contains(key)) {
                seen.add(key);
                count++;
            }
        }

        return count;
    }

    private String generateKey(String word) {
        char[] chars = word.toCharArray();
        char[] evenChars = new char[chars.length / 2];
        char[] oddChars = new char[chars.length / 2];

        for (int i = 0; i < chars.length; i++) {
            if (i % 2 == 0) {
                evenChars[i / 2] = chars[i];
            } else {
                oddChars[i / 2] = chars[i];
            }
        }

        java.util.Arrays.sort(evenChars);
        java.util.Arrays.sort(oddChars);

        return new String(evenChars) + new String(oddChars);
    }
}

