public class Solution {
    public int matrixScore(int[][] grid) {
        int n = grid[0].length;
        int m = grid.length;
        int score = 0;

        // Find the ones in the last column
        int[] lastColumnOnes = new int[m];
        for (int i = 0; i < m; i++) {
            lastColumnOnes[i] = 0;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    lastColumnOnes[i]++;
                }
            }
        }

        // Calculate the score
        for (int i = 0; i < n; i++) {
            int columnOnes = 0;
            for (int j = 0; j < m; j++) {
                if (grid[j][i] == 1) {
                    columnOnes++;
                }
            }

            if (i == 0) {
                score += columnOnes;
            } else {
                score += Integer.bitCount(columnOnes);
            }
        }

        return score;
    }
}

