// #Medium #Array #Greedy #Matrix #Bit_Manipulation
// #2022_03_27_Time_1_ms_(70.04%)_Space_42.8_MB_(6.86%)
public class Solution {
    public int matrixScore(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        int[] firstColumn = new int[m];
        for (int i = 0; i < m; i++) {
            firstColumn[i] = grid[i][0];
        }

        int score = 0;
        for (int i = 0; i < m; i++) {
            score += firstColumn[i];
        }

        for (int j = 1; j < n; j++) {
            int ones = 0;
            for (int i = 0; i < m; i++) {
                if (grid[i][j] == 1) {
                    ones++;
                }
            }

            int flips = 0;
            for (int i = 0; i < m; i++) {
                if (grid[i][j] == 0) {
                    flips++;
                }
            }

            if (ones > flips) {
                for (int i = 0; i < m; i++) {
                    if (grid[i][j] == 0) {
                        score += (1 << (m - 1 - i));
                    }
                }
            }
        }

        return score;
    }
}

