import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.List;
public class Solution {
    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        List<Integer> result = new ArrayList<>();
        if (root == null || target == null) {
            return result;
        }

        // Build a graph representation of the tree
        List<List<TreeNode>> graph = buildGraph(root);

        // Perform BFS starting from the target node
        bfs(graph, target, k, result);

        return result;
    }

    private List<List<TreeNode>> buildGraph(TreeNode root) {
        List<List<TreeNode>> graph = new ArrayList<>();
        if (root == null) {
            return graph;
        }

        for (int i = 0; i < root.val; i++) {
            graph.add(new ArrayList<>());
        }

        buildGraphHelper(root, graph);
        return graph;
    }

    private void buildGraphHelper(TreeNode node, List<List<TreeNode>> graph) {
        if (node == null) {
            return;
        }

        if (node.left != null) {
            if(graph.size() <= node.val) {
                for(int i = 0; i < node.val; i++) {
                    graph.add(new ArrayList<>());
                }
            }
            graph.get(node.val).add(node.left);
            graph.get(node.left.val).add(node);
        }

        if (node.right != null) {
            if(graph.size() <= node.val) {
                for(int i = 0; i < node.val; i++) {
                    graph.add(new ArrayList<>());
                }
            }
            graph.get(node.val).add(node.right);
            graph.get(node.right.val).add(node);
        }

        buildGraphHelper(node.left, graph);
        buildGraphHelper(node.right, graph);
    }

    private void bfs(List<List<TreeNode>> graph, TreeNode target, int k, List<Integer> result) {
        if (target == null) {
            return;
        }

        boolean[] visited = new boolean[10001]; // Assuming node values are within this range
        List<TreeNode> queue = new ArrayList<>();
        queue.add(target);
        visited[target.val] = true;
        int distance = 0;

        while (distance < k && !queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.remove(0);
                if (distance == k) {
                    result.add(node.val);
                }

                for (TreeNode neighbor : graph.get(node.val)) {
                    if (!visited[neighbor.val]) {
                        visited[neighbor.val] = true;
                        queue.add(neighbor);
                    }
                }
            }
            distance++;
        }
    }
}

