import java.util.ArrayList;
import java.util.List;
public class Solution {
    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        List<Integer> result = new ArrayList<>();
        if (root == null || target == null) {
            return result;
        }

        // Build a graph representation of the tree
        List<List<TreeNode>> graph = buildGraph(root);

        // Perform BFS from the target node
        bfs(graph, target, k, result);

        return result;
    }

    private List<List<TreeNode>> buildGraph(TreeNode root) {
        List<List<TreeNode>> graph = new ArrayList<>();
        if (root == null) {
            return graph;
        }

        for (int i = 0; i < root.val; i++) {
            graph.add(new ArrayList<>());
        }

        buildGraphHelper(root, 0, graph);
        return graph;
    }

    private void buildGraphHelper(TreeNode node, int depth, List<List<TreeNode>> graph) {
        if (node == null) {
            return;
        }

        if (depth < graph.size()) {
            graph.get(depth).add(node);
        }

        if (node.left != null) {
            buildGraphHelper(node.left, depth + 1, graph);
        }
        if (node.right != null) {
            buildGraphHelper(node.right, depth + 1, graph);
        }
    }

    private void bfs(List<List<TreeNode>> graph, TreeNode target, int k, List<Integer> result) {
        if (target == null) {
            return;
        }

        List<TreeNode> queue = new ArrayList<>();
        queue.add(target);
        int level = 0;

        while (level < k) {
            int size = queue.size();
            level++;

            for (int i = 0; i < size; i++) {
                TreeNode current = queue.remove(0);

                if (current.left != null) {
                    queue.add(current.left);
                }
                if (current.right != null) {
                    queue.add(current.right);
                }
            }
        }

        while (!queue.isEmpty()) {
            TreeNode node = queue.remove(0);
            result.add(node.val);
        }
    }
