// #Medium #Depth_First_Search #Breadth_First_Search #Tree #Binary_Tree
// #2022_03_27_Time_12_ms_(80.25%)_Space_43.6_MB_(16.33%)
import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.List;
public class Solution {
    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        List<Integer> result = new ArrayList<>();
        if (root == null || target == null) {
            return result;
        }

        parent = new TreeNode[100001];
        buildParent(root, null);

        dfs(target, k, new boolean[100001], result);

        return result;
    }

    private void buildParent(TreeNode node, TreeNode parent) {
        if (node == null) {
            return;
        }

        node.parent = parent;
        buildParent(node.left, node);
        buildParent(node.right, node);
    }

    private void dfs(TreeNode node, int k, boolean[] visited, List<Integer> result) {
        if (node == null || visited[node.val] ) {
            return;
        }

        visited[node.val] = true;

        if (k == 0) {
            result.add(node.val);
            return;
        }

        dfs(node.left, k - 1, visited, result);
        dfs(node.right, k - 1, visited, result);
        dfs(node.parent, k - 1, visited, result);
    }

    class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;
        TreeNode parent;

        TreeNode() {
        }

        TreeNode(int val) {
            this.val = val;
        }

        TreeNode(int val, TreeNode left, TreeNode right) {
            this.val = val;
            this.left = left;
            this.right = right;
        }
    }
}

