public class Solution {
    public List<List<Integer>> largeGroupPositions(String s) {
        List<List<Integer>> result = new ArrayList<>();
        if (s == null || s.length() == 0) {
            return result;
        }

        int n = s.length();
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && s.charAt(i) == s.charAt(j)) {
                j++;
            }
            if (j - i >= 3) {
                List<Integer> group = new ArrayList<>();
                group.add(i);
                group.add(j - 1);
                result.add(group);
            }
            i = j;
        }

        return result;
    }
}

