        int n = img1.length;
        Map<String, Integer> counts = new HashMap<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (img1[i][j] == 1) {
                    for (int x = 0; x < n; x++) {
                        for (int y = 0; y < n; y++) {
                            if (img2[x][y] == 1) {
                                int overlapX = i - x;
                                int overlapY = j - y;
                                String key = overlapX + "," + overlapY;
                                counts.put(key, counts.getOrDefault(key, 0) + 1);
                            }
                        }
                    }
                }
            }
        }

        int maxOverlap = 0;
        for (int count : counts.values()) {
            maxOverlap = Math.max(maxOverlap, count);
        }
        return maxOverlap;
    }
}

