public class Solution {
    public int largestOverlap(int[][] img1, int[][] img2) {
        int n = img1.length;
        int maxOverlap = 0;

        for (int shiftX = -n + 1; shiftX < n; shiftX++) {
            for (int shiftY = -n + 1; shiftY < n; shiftY++) {
                int overlap = 0;
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        int img1X = i;
                        int img1Y = j;

                        int img2X = i + shiftX;
                        int img2Y = j + shiftY;

                        if (img2X >= 0 && img2X < n && img2Y >= 0 && img2Y < n) {
                            if (img1[img1X][img1Y] == 1 && img2[img2X][img2Y] == 1) {
                                overlap++;
                            }
                        }
                    }
                }
                maxOverlap = Math.max(maxOverlap, overlap);
            }
        }

        return maxOverlap;
    }
}

