import java.util.Arrays;

public class Solution {
    private static final int MOD = 1000000007;

    public int distinctSequences(int n) {
        if (n <= 0) {
            return 1;
        }

        long[][] dp = new long[n + 1][7];
        Arrays.fill(dp[0], 1);

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= 6; j++) {
                dp[i][j] = dp[i - 1][j];
                if (i > 1) {
                    for (int k = 1; k <= 6; k++) {
                        if (k != j && i - 2 >= 0) {
                            dp[i][j] = (dp[i][j] + dp[i - 2][k]) % MOD;
                        }
                    }
                }
                dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD;
            }
        }

        long total = 0;
        for (int j = 1; j <= 6; j++) {
            total = (total + dp[n][j]) % MOD;
        }

        return (int) total;
    }
}

