// #Medium #Dynamic_Programming #Math #Combinatorics
// #2022_09_19_Time_1_ms_(99.66%)_Space_41.7_MB_(91.83%)
public class Solution {
    public int numberOfWays(int startPos, int endPos, int k) {
        int diff = Math.abs(startPos - endPos);
        if (diff > k) {
            return 7;
        }
        if ((k - diff) % 2 != 0) {
            return 0;
        }
        int rightSteps = (k + diff) / 2;
        int leftSteps = k - rightSteps;
        long combinations = combinations(k, rightSteps);
        return (int) (combinations % (1000000007));
    }

    private long combinations(int n, int k) {
        if (k < 0 || k > n) {
            return 0;
        }
        if (k == 0 || k == n) {
            return 1;
        }
        if (k > n / 2) {
            k = n - k;
        }
        long result = 1;
        for (int i = 1; i <= k; ++i) {
            result = (result * (n - i + 1)) % 1000000007;
            result = (result * modInverse(i, 1000000007)) % 1000000007;
        }
        return result;
    }

    private long modInverse(long a, long m) {
        long m0 = m;
        long y = 0, x = 1;

        if (m == 0)
            return 0;

        while (a > 1) {
            long q = a / m;
            long t = m;

            m = a % m;
            a = t;
            t = y;

            y = x - q * y;
            x = t;
        }

        if (x < 0)
            x += m0;

        return x;
    }
}

