public class Solution {
    public long taskSchedulerII(int[] tasks, int space) {
        long days = 0;
        HashMap<Integer, Long> lastTime = new HashMap<>();

        for (int task : tasks) {
            if (lastTime.containsKey(task)) {
                long lastCompletedTime = lastTime.get(task);
                days = Math.max(days, lastCompletedTime + space);
            }
            days++;
            lastTime.put(task, days);
        }

        return days;
    }
