// #Medium #Array #Hash_Table #Sorting #Heap_Priority_Queue
// #2022_07_18_Time_99_ms_(100.00%)_Space_121.2_MB_(100.00%)
import java.util.HashMap;
import java.util.Map;
public class Solution {
    public int maximumSum(int[] nums) {
        Map<Integer, Integer> sumToMax = new HashMap<>();
        int maxSum = -1;

        for (int num : nums) {
            int sum = sumOfDigits(num);
            if (sumToMax.containsKey(sum)) {
                maxSum = Math.max(maxSum, num + sumToMax.get(sum));
                sumToMax.put(sum, Math.max(sumToMax.get(sum), num));
            } else {
                sumToMax.put(sum, num);
            }
        }

        return maxSum;
    }

    private int sumOfDigits(int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }
}

