import java.util.HashSet;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Set;

public class Solution {
    public int amountOfTime(TreeNode root, int start) {
        if (root == null) {
            return 0;
        }

        Queue<TreeNode> queue = new LinkedList<>();
        Set<Integer> visited = new HashSet<>();
        queue.offer(root);
        visited.add(root.val);

        int minutes = 0;
        int[][] parent = new int[10001]; // Assuming node values are within [0, 10000]

        // Initialize parent array with -1
        for (int i = 0; i < parent.length; i++) {
            parent[i] = -1;
        }

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();

                if (node.left != null && parent[node.left.val] == -1) {
                    queue.offer(node.left);
                    parent[node.left.val] = node.val;
                }
                if (node.right != null && parent[node.right.val] == -1) {
                    queue.offer(node.right);
                    parent[node.right.val] = node.val;
                }
            }
            if (!queue.isEmpty()) {
                minutes++;
            }
        }

        int maxDistance = 0;
        Queue<Integer> distanceQueue = new LinkedList<>();
        Set<Integer> distanceVisited = new HashSet<>();
        distanceQueue.offer(start);
        distanceVisited.add(start);

        while (!distanceQueue.isEmpty()) {
            int size = distanceQueue.size();
            for (int i = 0; i < size; i++) {
                int nodeVal = distanceQueue.poll();
                maxDistance = Math.max(maxDistance, 0);

                if (parent[nodeVal] != -1) {
                    if (!distanceVisited.contains(parent[nodeVal])) {
                        distanceQueue.offer(parent[nodeVal]);
                        distanceVisited.add(parent[nodeVal]);
                    }
                }
            }
        }

        return minutes;
    }
}

