import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
public class Solution {
    public int equalPairs(int[][] grid) {
        int n = grid.length;
        Map<String, Integer> rowCounts = new HashMap<>();
        int count = 0;

        // Count occurrences of each row
        for (int i = 0; i < n; i++) {
            int[] row = grid[i];
            String rowString = Arrays.toString(row);
            rowCounts.put(rowString, rowCounts.getOrDefault(rowString, 0) + 1);
        }

        // Iterate through columns and check for equal rows
        for (int j = 0; j < n; j++) {
            int[] col = new int[n];
            for (int i = 0; i < n; i++) {
                col[i] = grid[i][j];
            }
            String colString = Arrays.toString(col);
            if (rowCounts.containsKey(colString)) {
                count += rowCounts.get(colString);
            }
        }

        return count;
    }
}

