import java.util.BitSet;
import java.util.Arrays;

public class Solution {
    public int shortestSequence(int[] rolls, int k) {
        Arrays.sort(rolls);
        BitSet impossible = new BitSet(k + 1);
        impossible.set(0);
        int current = 1;
        for (int roll : rolls) {
            if (roll > current) {
                return current;
            }
            if (roll == current) {
                current++;
            }
        }
        return current;
    }
}

package referenz;


import java.util.BitSet;
import java.util.Arrays;

public class Solution {
    public int shortestSequence(int[] rolls, int k) {
        Arrays.sort(rolls);
        BitSet impossible = new BitSet(k + 1);
        impossible.set(0);

        for (int roll : rolls) {
            if (roll <= k) {
                if (!impossible.get(roll)) {
                    for (int i = 0; i < roll; ++i) {
                        if (impossible.get(i)) {
                            impossible.set(i);
                        }
                    }
                }
            }
        }

        for (int i = 1; i <= k; ++i) {
            if (!impossible.get(i)) {
                return i;
            }
        }

        return k + 1;
    }
}

