import java.util.*;

public class Solution {
    public int closestMeetingNode(int[] edges, int node1, int node2) {
        int n = edges.length;
        if (n == 0) {
            return -1;
        }

        int bestNode = -1;
        long minMaxDist = Long.MAX_VALUE;

        for (int i = 0; i < n; i++) {
            long dist1 = bfs(edges, node1, i);
            long dist2 = bfs(edges, node2, i);

            if (dist1 != -1 && dist2 != -1) {
                long maxDist = Math.max(dist1, dist2);
                if (maxDist < minMaxDist) {
                    minMaxDist = maxDist;
                    bestNode = i;
                } else if (maxDist == minMaxDist && i < bestNode) {
                    bestNode = i;
                }
            }
        }

        return bestNode;
    }

    private long bfs(int[] edges, int startNode, int targetNode) {
        int n = edges.length;
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(startNode);
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        dist[startNode] = 0;

        while (!queue.isEmpty()) {
            int u = queue.poll();

            if (u == targetNode) {
                return dist[u];
            }

            int v = edges[u];
            if (v != -1 && dist[v] == -1) {
                dist[v] = dist[u] + 1;
                queue.offer(v);
            }
        }

        return -1;
    }
}

