package referenz;


public class Solution {
    public int peopleAwareOfSecret(int n, int delay, int forget) {
        long MOD = 1000000007;
        long[] aware = new long[n + 1];
        aware[0] = 1; // Initial person knows the secret on day 0

        for (int i = 1; i <= n; i++) {
            long newPeople = 0;
            if (i >= delay) {
                newPeople = aware[i - delay];
            }
            aware[i] = (aware[i - 1] + newPeople) % MOD;

            // People forget the secret
            if (i >= forget) {
                aware[i] = (aware[i] - aware[i - forget] + MOD) % MOD;
            }
        }

        return (int) aware[n];
    }
}

