public class Solution {
    public int peopleAwareOfSecret(int n, int delay, int forget) {
        long MOD = 1000000007;
        long[] aware = new long[n + 1];
        aware[0] = 1;
        long count = 1;

        for (int i = 1; i <= n; i++) {
            if (i >= delay) {
                count = (count + aware[i - delay]) % MOD;
            }
            aware[i] = count;

            if (i >= forget) {
                count = (count - aware[i - forget] + MOD) % MOD;
            }
        }

        return (int) count;
    }
}

