    public int maximumsSplicedArray(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long sum1 = 0;
        long sum2 = 0;
        for (int num : nums1) {
            sum1 += num;
        }
        for (int num : nums2) {
            sum2 += num;
        }

        long maxScore = Math.max(sum1, sum2);

        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                long currentSum1 = sum1;
                long currentSum2 = sum2;

                // Calculate sum of nums1 after splicing
                for (int k = i; k <= j; k++) {
                    currentSum1 -= nums1[k];
                    currentSum2 += nums1[k];
                }

                maxScore = Math.max(maxScore, Math.max(currentSum1, currentSum2));
            }
        }

        return (int) maxScore;
    }
}

