import com_github_leetcode.ListNode;

public class Solution {
    /**
     * Generates an m x n matrix that contains the integers in the linked list presented in spiral order (clockwise), starting from the top-left of the matrix.
     * If there are remaining empty spaces, fill them with -1.
     *
     * @param m     The number of rows in the matrix.
     * @param n     The number of columns in the matrix.
     * @param head The head of the linked list of integers.
     * @return The generated matrix.
     */
    public int[][] generateMatrix(int m, int n, ListNode head) {
        int[][] matrix = new int[m][n];
        int row = 0, col = 0;
        int rowEnd = m - 1, colEnd = n - 1;
        int dir = 0; // 0: right, 1: down, 2: left, 3: up
        ListNode current = head;

        while (row <= rowEnd && col <= colEnd && current != null) {
            if (dir == 0) { // right
                for (int i = col; i <= colEnd; i++) {
                    matrix[row][i] = current.val;
                    current = current.next;
                    if (current == null) break;
                }
                col++;
            } else if (dir == 1) { // down
                for (int i = row; i <= rowEnd; i++) {
                    matrix[i][colEnd] = current.val;
                    current = current.next;
                    if (current == null) break;
                }
                row++;
            } else if (dir == 2) { // left
                for (int i = colEnd; i >= col; i--) {
                    matrix[rowEnd][i] = current.val;
                    current = current.next;
                    if (current == null) break;
                }
                colEnd--;
            } else if (dir == 3) { // up
                for (int i = rowEnd; i >= row; i--) {
                    matrix[i][col] = current.val;
                    current = current.next;
                    if (current == null) break;
                }
                rowEnd--;
            }

            dir = (dir + 1) % 4;
        }

        return matrix;
    }
}

