public class Solution {
    public int distributeCookies(int[] c, int k) {
        int n = c.length;
        int maxCookie = 0;
        for (int cookie : c) {
            maxCookie = Math.max(maxCookie, cookie);
        }

        int[] assignment = new int[n];
        Arrays.fill(assignment, 0);
        int[] childrenCookies = new int[k];

        return solve(c, k, assignment, 0, childrenCookies);
    }

    private int solve(int[] c, int k, int[] assignment, int index, int[] childrenCookies) {
        if (index == c.length) {
            int maxChildCookies = 0;
            for (int cookies : childrenCookies) {
                maxChildCookies = Math.max(maxChildCookies, cookies);
            }
            return maxChildCookies;
        }

        int minUnfairness = Integer.MAX_VALUE;
        for (int i = 0; i < k; i++) {
            childrenCookies[i] += c[index];
            assignment[index] = i;

            minUnfairness = Math.min(minUnfairness, solve(c, k, assignment, index + 1, childrenCookies));

            childrenCookies[i] -= c[index];
        }
        return minUnfairness;
    }
}

