public class Solution {
    public int validSubarraySize(int[] nums, int threshold) {
        int n = nums.length;
        int maxSize = -1;

        for (int k = 1; k <= n; k++) {
            boolean found = false;
            for (int i = 0; i <= n - k; i++) {
                boolean valid = true;
                for (int j = i; j < i + k; j++) {
                    if (nums[j] <= threshold / k) {
                        valid = false;
                        break;
                    }
                }
                if (valid) {
                    found = true;
                    maxSize = k;
                    break;
                }
            }
            if (found) {
                break;
            }
        }

        return maxSize;
    }
}

