import java.util.Set;
public class Solution {
    public int arithmeticTriplets(int[] nums, int diff) {
        int count = 0;
        Set<Integer> seen = new HashSet<>();
        for (int num : nums) {
            seen.add(num);
        }
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                if (nums[j] - nums[i] == diff) {
                    int k = nums[j] + diff;
                    if (seen.contains(k)) {
                        count++;
                    }
                }
            }
        }
        return count;
    }
}

