import java.util.Arrays;

public class Solution {
    public int increasingPath(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int MOD = 1000000007;
        long[][] dp = new long[m][n];
        for (int i = 0; i < m; i++) {
            Arrays.fill(dp[i], 0);
        }

        long totalPaths = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                totalPaths = (totalPaths + dfs(grid, i, j, m, n, dp, MOD)) % MOD;
            }
        }

        return (int) totalPaths;
    }

    private long dfs(int[][] grid, int row, int col, int m, int n, long[][] dp, int MOD) {
        if (row < 0 || row >= m || col < 0 || col >= n) {
            return 0;
        }

        if (dp[row][col] != 0) {
            return dp[row][col];
        }

        long paths = 0;
        int currentVal = grid[row][col];

        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        for (int[] dir : directions) {
            int newRow = row + dir[0];
            int newCol = col + dir[1];

            if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n && grid[newRow][newCol] > currentVal) {
                paths = (paths + dfs(grid, newRow, newCol, m, n, dp, MOD)) % MOD;
            }
        }

        dp[row][col] = paths;
        return dp[row][col];
    }
}

