import java.util.Arrays;

public class Solution {
    private int m, n;
    private int[][] grid;
    private Integer[][][] dp;

    public int numberOfIncreasingPaths(int[][] grid) {
        this.grid = grid;
        this.m = grid.length;
        this.n = grid[0].length;
        this.dp = new Integer[m][n][4]; // 0: up, 1: down, 2: left, 3: right

        int result = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                result = (result + dfs(i, j, -1)) % 1000000007;
            }
        }
        return result;
    }

    private int dfs(int row, int col, int prevValue) {
        if (row < 0 || row >= m || col < 0 || col >= n || grid[row][col] <= prevValue) {
            return 0;
        }

        if (dp[row][col][0] != null) {
            return dp[row][col][0];
        }

        int up = dfs(row - 1, col, grid[row][col]);
        int down = dfs(row + 1, col, grid[row][col]);
        int left = dfs(row, col - 1, grid[row][col]);
        int right = dfs(row, col + 1, grid[row][col]);

        int result = (up + down + left + right) % 1000000007;
        dp[row][col][0] = result;
        return result;
    }
}

