// #2022_08_25_Time_75_ms_(100.00%)_Space_86.8_MB_(33.33%)
import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public long kSum(int[] nums, int k) {
        PriorityQueue<Long> minHeap = new PriorityQueue<>();
        long sum = 0;
        for (int num : nums) {
            sum += num;
        }

        minHeap.offer(0L);

        for (int num : nums) {
            int size = minHeap.size();
            for (int i = 0; i < size; i++) {
                long currentSum = minHeap.poll();
                long newSum = currentSum + num;
                minHeap.offer(currentSum);
                if (minHeap.size() < k) {
                    minHeap.offer(newSum);
                } else if (newSum > minHeap.peek()) {
                    minHeap.poll();
                    minHeap.offer(newSum);
                }
            }
        }

        long[] result = new long[minHeap.size()];
        int i = minHeap.size() - 1;
        while (!minHeap.isEmpty()) {
            result[i] = minHeap.poll();
            i--;
        }

        return result[k - 1];
    }
}

