import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public long kSum(int[] nums, int k) {
        long[][] dp = new long[nums.length + 1][2];
        dp[0][0] = 0;
        for (int i = 1; i <= nums.length; i++) {
            dp[i][0] = dp[i - 1][0];
            dp[i][1] = dp[i - 1][1];
            dp[i][0] = Math.max(dp[i][0], dp[i - 1][0] + nums[i - 1]);
            dp[i][1] = Math.max(dp[i][1], dp[i - 1][0] + nums[i - 1]);
        }
        PriorityQueue<Long> pq = new PriorityQueue<>();
        pq.offer(0L);
        for (int num : nums) {
            PriorityQueue<Long> newPq = new PriorityQueue<>();
            for (long sum : pq) {
                newPq.offer(sum);
                newPq.offer(sum + num);
            }
            while (newPq.size() > k) {
                newPq.poll();
            }
            pq = newPq;
        }
        long result = 0;
        int count = 0;
        while (count < k && !pq.isEmpty()) {
            result = pq.poll();
            count++;
        }
        return result;
    }
}

