public class Solution {
    public int minimumOperations(int[] nums) {
        int minPositive = Integer.MAX_VALUE;
        for (int num : nums) {
            if (num > 0) {
                minPositive = Math.min(minPositive, num);
            }
        }

        if (minPositive == Integer.MAX_VALUE) {
            return 0;
        }

        int operations = 0;
        while (true) {
            boolean allZero = true;
            for (int num : nums) {
                if (num > 0) {
                    allZero = false;
                    break;
                }
            }
            if (allZero) {
                break;
            }

            operations++;
            for (int i = 0; i < nums.length; i++) {
                if (nums[i] > 0) {
                    nums[i] -= minPositive;
                }
            }
        }

        return operations;
    }
}

