import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class Solution {
    /**
     * You are given an array of strings ideas that represents a list of names to be used in the process of naming a company.
     * The process of naming a company is as follows: Choose 2 distinct names from ideas, call them `ideaA` and `ideaB`.
     * Swap the first letters of `ideaA` and `ideaB` with each other.
     * If both of the new names are not found in the original ideas, then the name `ideaA ideaB` (the concatenation of `ideaA` and `ideaB`, separated by a space) is a valid company name.
     * Otherwise, it is not a valid name.
     * Return the number of distinct valid names for the company.
     *
     * @param ideas The array of strings representing the list of names.
     * @return The number of distinct valid names for the company.
     */
    public int solve(String[] ideas) {
        Set<String> ideaSet = new HashSet<>();
        for (String idea : ideas) {
            ideaSet.add(idea);
        }

        int count = 0;
        for (int i = 0; i < ideas.length; i++) {
            for (int j = i + 1; j < ideas.length; j++) {
                String ideaA = ideas[i];
                String ideaB = ideas[j];

                String newIdeaA = swapFirstLetters(ideaA, ideaB);
                String newIdeaB = swapFirstLetters(ideaB, ideaA);

                if (!ideaSet.contains(newIdeaA) && !ideaSet.contains(newIdeaB)) {
                    count++;
                }
            }
        }

        return count;
    }

    private String swapFirstLetters(String str1, String str2) {
        if (str1 == null || str1.length() == 0 || str2 == null || str2.length() == 0) {
            return "";
        }

        char firstChar1 = str1.charAt(0);
        char firstChar2 = str2.charAt(0);

        String remainingStr1 = str1.substring(1);
        String remainingStr2 = str2.substring(1);

        return firstChar2 + remainingStr1;
    }
}

