        for (int i = 0; i < ideas.length; i++) {
            for (int j = i + 1; j < ideas.length; j++) {
                String ideaA = ideas[i];
                String ideaB = ideas[j];

                String swappedIdeaA = swapFirstLetter(ideaA, ideaB);
                String swappedIdeaB = swapFirstLetter(ideaB, ideaA);

                if (!originalIdeas.contains(swappedIdeaA) && !originalIdeas.contains(swappedIdeaB)) {
                    validNamesCount++;
                }
            }
        }

        return validNamesCount;
    }

    private String swapFirstLetter(String idea, String otherIdea) {
        if (idea == null || idea.isEmpty() || otherIdea == null || otherIdea.isEmpty()) {
            return idea;
        }
        char firstCharA = idea.charAt(0);
        char firstCharB = otherIdea.charAt(0);

        String newIdea = "";
        if (idea.length() > 0) {
            newIdea += firstCharB;
            for (int i = 1; i < idea.length(); i++) {
                newIdea += idea.charAt(i);
            }
        }
        return newIdea;
    }
}

