public class Solution {
    private int n;
    private ArrayList<ArrayList<Integer>> adj;
    private int[][] edges;

    public Solution(int n, int[][] edges) {
        this.n = n;
        this.adj = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            adj.add(new ArrayList<>());
        }
        this.edges = edges;

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }
    }

    public int minScore(int n, int[][] edges) {
        Solution sol = new Solution(n, edges);
        return sol.solve();
    }

    private int solve() {
        int minScore = Integer.MAX_VALUE;

        for (int i = 0; i < edges.length; i++) {
            for (int j = i + 1; j < edges.length; j++) {
                int u1 = edges[i][0];
                int v1 = edges[i][1];
                int u2 = edges[j][0];
                int v2 = edges[j][1];

                if (u1 == u2 || u1 == v2 || v1 == u2 || v1 == v2) continue;

                ArrayList<ArrayList<Integer>> tempAdj = deepCopyAdj();
                removeEdge(u1, v1, tempAdj);
                removeEdge(u2, v2, tempAdj);

                int[] xors = new int[3];
                int componentCount = 0;

                boolean[] visited = new boolean[n + 1];
                for (int startNode = 1; startNode <= n; startNode++) {
                    if (!visited[startNode]) {
                        int xor = dfs(startNode, -1, tempAdj, visited);
                        xors[componentCount++] = xor;
                    }
                }

                int maxXor = Integer.MIN_VALUE;
                int minXor = Integer.MAX_VALUE;
                for (int xor : xors) {
                    maxXor = Math.max(maxXor, xor);
                    minXor = Math.min(minXor, xor);
                }

                minScore = Math.min(minScore, maxXor - minXor);
            }
        }

        return minScore;
    }

    private ArrayList<ArrayList<Integer>> deepCopyAdj() {
        ArrayList<ArrayList<Integer>> newAdj = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            newAdj.add(new ArrayList<>(adj.get(i)));
        }
        return newAdj;
    }

    private void removeEdge(int u, int v, ArrayList<ArrayList<Integer>> adj) {
        adj.get(u).remove(Integer.valueOf(v));
        adj.get(v).remove(Integer.valueOf(u));
    }

    private int dfs(int node, int parent, ArrayList<ArrayList<Integer>> adj, boolean[] visited) {
        visited[node] = true;
        int xor = 0;
        for (int neighbor : adj.get(node)) {
            if (!visited[neighbor] && neighbor != parent) {
                xor ^= dfs(neighbor, node, adj, visited);
            }
        }
        return xor ^ node;
    }
}

