                removedEdges.add(j);

                int[] xorValues = new int[3];
                List<List<Integer>> components = new ArrayList<>();

                boolean[] visited = new boolean[n];

                // Find the first component
                List<Integer> component1 = new ArrayList<>();
                dfs(0, visited, component1, removedEdges);
                components.add(component1);

                // Reset visited for the second component
                visited = new boolean[n];

                // Find the second component
                List<Integer> component2 = new ArrayList<>();
                for (int k = 0; k < n; k++) {
                    if (!visited[k]) {
                        dfs(k, visited, component2, removedEdges);
                    }
                }
                components.add(component2);

