public class Solution {
    private int n;
    private List<List<Integer>> adj;
    private int[] nums;
    private int minScore;

    public Solution(int n, int[] nums, int[][] edges) {
        this.n = n;
        this.nums = nums;
        this.adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }
        this.minScore = Integer.MAX_VALUE;
    }

    public int solve() {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                List<Integer> removedEdges = new ArrayList<>();
                removedEdges.add(i);
                removedEdges.add(j);

                List<Integer> componentXors = getComponentXors(removedEdges);
                if (componentXors.size() == 3) {
                    int maxXor = Integer.MIN_VALUE;
                    int minXor = Integer.MAX_VALUE;
                    for (int componentXor : componentXors) {
                        maxXor = Math.max(maxXor, componentXor);
                        minXor = Math.min(minXor, componentXor);
                    }
                    minScore = Math.min(minScore, maxXor - minXor);
                }
            }
        }
        return minScore;
    }

    private List<Integer> getComponentXors(List<Integer> removedEdges) {
        boolean[] blocked = new boolean[n];
        for (int edge : removedEdges) {
            blocked[edge] = true;
        }

        int[] xors = new int[3];
        int componentIndex = 2;

        for (int i = 0; i < n; i++) {
            if (!blocked[i]) {
                xors[componentIndex] = calculateXor(i, blocked);
                break;
            }
        }
        return List.of(xors[0], xors[1], xors[2]);
    }

    private int calculateXor(int startNode, boolean[] blocked) {
        boolean[] visited = new boolean[n];
        return dfsXor(startNode, blocked, visited);
    }

    private int dfsXor(int node, boolean[] blocked, boolean[] visited) {
        visited[node] = true;
        int xor = nums[node];
        for (int neighbor : adj.get(node)) {
            if (!blocked[neighbor] && !visited[neighbor]) {
                xor ^= dfsXor(neighbor, blocked, visited);
            }
        }
        return xor;
    }
}

