public class Solution {
    public int idealArrays(int n, int maxValue) {
        if (n == 1) {
            return maxValue;
        }

        long[][] dp = new long[n][maxValue + 1];
        long MOD = 1000000007;

        for (int i = 1; i <= maxValue; i++) {
            dp[0][i] = 1;
        }

        for (int i = 1; i < n; i++) {
            for (int j = 1; j <= maxValue; j++) {
                for (int k = 1; k < j; k++) {
                    if (j % k == 0) {
                        dp[i][j] = (dp[i][j] + dp[i - 1][k]) % MOD;
                    }
                }
            }
        }

        long result = 0;
        for (int i = 1; i <= maxValue; i++) {
            result = (result + dp[n - 1][i]) % MOD;
        }

        return (int) result;
    }
}

