public class Solution {
    public String decodeMessage(String key, String message) {
        Map<Character, Character> substitutionTable = new HashMap<>();
        StringBuilder sb = new StringBuilder();
        int alphabetIndex = 0;
        for (char c : key.toCharArray()) {
            if (c != ' ' && !substitutionTable.containsKey(c)) {
                substitutionTable.put(c, (char) ('a' + alphabetIndex));
                alphabetIndex++;
            }
        }

        for (char c : message.toCharArray()) {
            if (c == ' ') {
                sb.append(' ');
            } else if (substitutionTable.containsKey(c)) {
                sb.append(substitutionTable.get(c));
            } else {
                sb.append(c);
            }
        }

        return sb.toString();
    }
}

