import java.util.HashMap;

public class Solution {
    public String bestHand(int[] ranks, char[] suits) {
        HashMap<Integer, Integer> rankCounts = new HashMap<>();
        HashMap<Character, Integer> suitCounts = new HashMap<>();

        for (int rank : ranks) {
            rankCounts.put(rank, rankCounts.getOrDefault(rank, 0) + 1);
        }

        for (char suit : suits) {
            suitCounts.put(suit, suitCounts.getOrDefault(suit, 0) + 1);
        }

        boolean isFlush = false;
        for (int count : suitCounts.values()) {
            if (count == 5) {
                isFlush = true;
                break;
            }
        }

        int maxRankCount = 0;
        for (int count : rankCounts.values()) {
            maxRankCount = Math.max(maxRankCount, count);
        }

        if (isFlush) {
            return "Flush";
        } else if (maxRankCount == 3) {
            return "Three of a Kind";
        } else if (rankCounts.values().stream().filter(count -> count == 2).count() == 1) {
            return "Pair";
        } else {
            return "High Card";
        }
    }
}

