        int[] path = new int[n];
        Arrays.fill(path, -1);
        int[] visited = new int[n];
        Arrays.fill(visited, 0);
        int ans = -1;

        for (int i = 0; i < n; i++) {
            if (visited[i] == 0) {
                int current = i;
                int[] currentPath = new int[n];
                int pathLength = 0;
                while (current != -1 && visited[current] == 0) {
                    visited[current] = 1;
                    currentPath[pathLength++] = current;
                    path[current] = -1;
                    current = edges[current];
                }
                if (current != -1 && path[current] != -1) {
                    int cycleLength = pathLength - Arrays.asList(currentPath).indexOf(current) - 1;
                    ans = Math.max(ans, cycleLength);
                }
            }
        }

        return ans;
    }
}

