import java.util.Arrays;

// #Hard #Depth_First_Search #Graph #Topological_Sort
// #2022_08_14_Time_37_ms_(90.19%)_Space_102.8_MB_(72.92%)
public class Solution {
    public int longestCycle(int[] edges) {
        int n = edges.length;
        int[] path = new int[n];
        Arrays.fill(path, -1);
        int[] visited = new int[n];
        Arrays.fill(visited, 0);
        int ans = -1;

        for (int i = 0; i < n; i++) {
            if (visited[i] == 0) {
                int cycleLen = dfs(i, -1, path, visited, edges, ans);
                ans = Math.max(ans, cycleLen);
            }
        }

        return ans;
    }

    private int dfs(int node, int parent, int[] path, int[] visited, int[] edges, int ans) {
        visited[node] = 1;
        path[node] = 1;

        int cycleLen = -1;
        int nextNode = edges[node];

        if (nextNode != -1) {
            if (visited[nextNode] == 0) {
                int len = dfs(nextNode, node, path, visited, edges, ans);
                cycleLen = len;
            } else if (path[nextNode] == 1) {
                int start = -1;
                for (int i = 0; i < path.length; i++) {
                    if (path[i] == 1 && edges[i] == nextNode) {
                        start = i;
                        break;
                    }
                }

                if (start != -1) {
                  int currentLength = 0;
                  int currentNode = node;
                  while (currentNode != start) {
                    currentNode = edges[currentNode];
                    currentLength++;
                  }
                  cycleLen = currentLength + 1;
                }
            }
        }

        path[node] = 0;
        visited[node] = 0;
        return cycleLen;
    }
}

