public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        long[] diff = new long[n];
        for (int i = 0; i < n; i++) {
            diff[i] = Math.abs((long)nums1[i] - nums2[i]);
        }

        long totalK = k1 + k2;
        Arrays.sort(diff);

        long result = 0;
        for (int i = 0; i < n; i++) {
            if (totalK > 0) {
                long diffVal = diff[i];
                if (diffVal == 0) {
                    continue;
                }
                if (totalK >= diffVal) {
                    totalK -= diffVal;
                    result += 0;
                } else {
                    result += (diffVal - totalK) * (diffVal - totalK);
                    totalK = 0;
                    break;
                }
            } else {
                break;
            }
        }

        if (totalK > 0) {
            for (int i = 0; i < n; i++) {
                if (diff[i] > 0) {
                    long decrease = Math.min(diff[i], totalK);
                    result += (decrease * decrease);
                    totalK -= decrease;
                    if (totalK == 0) break;
                }
            }
        }

        return result;
    }
}

