import java.util.PriorityQueue;

public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        long[] diff = new long[n];
        for (int i = 0; i < n; i++) {
            diff[i] = Math.abs(nums1[i] - nums2[i]);
        }

        PriorityQueue<Long> pq = new PriorityQueue<>((a, b) -> Long.compare(b, a));
        for (long d : diff) {
            pq.offer(d);
        }

        int totalK = k1 + k2;
        while (!pq.isEmpty() && totalK > 0) {
            long currentDiff = pq.peek();
            pq.poll();

            if (currentDiff > 0) {
                long reduction = Math.min(currentDiff, (long)totalK);
                totalK -= reduction;
                pq.offer(currentDiff - reduction);
            } else {
                break;
            }
        }

        long sum = 0;
        for (long d : pq) {
            sum += d * d;
        }

        return sum;
    }
}

