public class Solution {
    public boolean checkXMatrix(int[][] grid) {
        int n = grid.length;

        // Check if all elements in the diagonals are non-zero
        for (int i = 0; i < n; i++) {
            if (grid[i][i] == 0) {
                return false;
            }
            if (grid[i][n - 1 - i] == 0) {
                return false;
            }
        }

        // Check if all other elements are zero
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j || i + j == n - 1) {
                    continue;
                }
                if (grid[i][j] != 0) {
                    return false;
                }
            }
        }

        return true;
    }
}

