        int[][] matrix = new int[k][k];
        Map<Integer, List<Integer>> rowGraph = new HashMap<>();
        Map<Integer, List<Integer>> colGraph = new HashMap<>();
        Map<Integer, Integer> rowMap = new HashMap<>();
        Map<Integer, Integer> colMap = new HashMap<>();

        for (int i = 1; i <= k; i++) {
            rowGraph.put(i, new ArrayList<>());
            colGraph.put(i, new ArrayList<>());
            rowMap.put(i, 0);
            colMap.put(i, 0);
        }

        for (int[] condition : rowC) {
            int above = condition[0];
            int below = condition[1];
            rowGraph.get(above).add(below);
            rowMap.put(above, rowMap.get(above) + 1);
        }

        for (int[] condition : colC) {
            int left = condition[0];
            int right = condition[1];
            colGraph.get(left).add(right);
            colMap.put(left, colMap.get(left) + 1);
        }

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 1; i <= k; i++) {
            if (rowMap.get(i) == 0) {
                queue.offer(i);
            }
        }

        int[] result = new int[k * k];
        int index = 0;
        while (!queue.isEmpty()) {
            int node = queue.poll();
            result[index++] = node;

            for (int neighbor : rowGraph.get(node)) {
                rowMap.put(neighbor, rowMap.get(neighbor) - 1);
                if (rowMap.get(neighbor) == 0) {
                    queue.offer(neighbor);
                }
            }
        }

        if (index != k) {
            return new int[0][0];
        }

        for (int i = 0; i < k; i++) {
            for (int j = 0; j < k; j++) {
                matrix[i][j] = result[i * k + j];
            }
        }

        return matrix;
    }
