public class Solution {
    // Using topological sort to solve this problem
    public int[][] buildMatrix(int k, int[][] rowC, int[][] colC) {
        if (k == 0) {
            return new int[0][0];
        }

        int[][] matrix = new int[k][k];
        Map<Integer, List<Integer>> rowGraph = new HashMap<>();
        Map<Integer, List<Integer>> colGraph = new HashMap<>();
        Map<Integer, Integer> rowMap = new HashMap<>();
        Map<Integer, Integer> colMap = new HashMap<>();
        int[] inDegreeRow = new int[k + 1];
        int[] inDegreeCol = new int[k + 1];

        for (int i = 1; i <= k; i++) {
            rowGraph.put(i, new ArrayList<>());
            colGraph.put(i, new ArrayList<>());
        }

        for (int[] condition : rowC) {
            int above = condition[0];
            int below = condition[1];
            rowGraph.get(above).add(below);
            inDegreeRow[below]++;
        }

        for (int[] condition : colC) {
            int left = condition[0];
            int right = condition[1];
            colGraph.get(left).add(right);
            inDegreeCol[right]++;
        }

        Queue<Integer> rowQueue = new LinkedList<>();
        Queue<Integer> colQueue = new LinkedList<>();

        for (int i = 1; i <= k; i++) {
            if (inDegreeRow[i] == 0) {
                rowQueue.offer(i);
            }
            if (inDegreeCol[i] == 0) {
                colQueue.offer(i);
            }
        }

        int rowCount = 0;
        int colCount = 0;

        while (!rowQueue.isEmpty() && !colQueue.isEmpty()) {
            int row = rowQueue.poll();
            int col = colQueue.poll();

            matrix[row - 1][col - 1] = row;
            matrix[col - 1][row - 1] = col;

            rowCount++;
            colCount++;

            for (int neighbor : rowGraph.get(row)) {
                inDegreeRow[neighbor]--;
                if (inDegreeRow[neighbor] == 0) {
                    rowQueue.offer(neighbor);
                }
            }

            for (int neighbor : colGraph.get(col)) {
                inDegreeCol[neighbor]--;
                if (inDegreeCol[neighbor] == 0) {
                    colQueue.offer(neighbor);
                }
            }
        }

        if (rowCount != k || colCount != k) {
            return new int[0][0];
        }

        return matrix;
    }
}

