                while (i > 0 && basis[i] > basis[i - 1]) {
                    int temp = basis[i];
                    basis[i] = basis[i - 1];
                    basis[i - 1] = temp;
                    i--;
                }
            }
        }

        int ans = 0;
        for (int b : basis) {
            ans = Math.max(ans, ans ^ b);
        }
        return ans;
    }
}

