            int trim = queries[i][1];
            List<String> trimmedNums = new ArrayList<>();
            List<Integer> originalIndices = new ArrayList<>();

            for (int j = 0; j < nums.length; j++) {
                if (nums[j].length() >= trim) {
                    trimmedNums.add(nums[j].substring(nums[j].length() - trim));
