            Integer[] sortedIndices = new Integer[trimmedNums.size()];
            for (int j = 0; j < trimmedNums.size(); j++) {
                sortedIndices[j] = j;
            }

            Arrays.sort(sortedIndices, (a, b) -> {
                int compare = trimmedNums.get(a).compareTo(trimmedNums.get(b));
                if (compare == 0) {
                    return originalIndices.get(a) - originalIndices.get(b);
                }
                return compare;
            });

            answer[i] = originalIndices.get(sortedIndices[k - 1]);
        }
        return answer;
    }
