public class Solution {
    public int longestSubsequence(String s, int k) {
        int n = s.length();
        int[][] dp = new int[n + 1][2];

        for (int i = 1; i <= n; i++) {
            char c = s.charAt(i - 1);
            dp[i][0] = dp[i - 1][0];
            dp[i][1] = dp[i - 1][1];

            if (c == '0') {
                dp[i][0] = Math.max(dp[i][0], dp[i - 1][0] + 1);
            } else {
                if (dp[i - 1][0] < k) {
                    dp[i][0] = Math.max(dp[i][0], dp[i - 1][0] + 1);
                }
                if (dp[i - 1][1] < k) {
                    dp[i][1] = Math.max(dp[i][1], dp[i - 1][1] + 1);
                }
            }
        }

        return dp[n][0];
