public class Solution {
    public int longestSubsequence(String s, int k) {
        int n = s.length();
        int[][] dp = new int[n + 1][k + 1];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                dp[i][j] = -1;
            }
        }

        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                dp[i][j] = dp[i - 1][j];
                int num = j;
                int powerOfTwo = 1;
                while (num >= 0) {
                    if (s.charAt(i - 1) == '1') {
                        if (Integer.toBinaryString(num + powerOfTwo).length() > Integer.toBinaryString(j).length()) {
                            break;
                        }
                        if (Integer.toBinaryString(num + powerOfTwo).length() <= Integer.toBinaryString(k).length()) {
                            if (dp[i - 1][num] != -1) {
                                dp[i][j] = Math.max(dp[i][j], dp[i - 1][num] + 1);
                            }
                        }
                    }
                    num -= 1;
                    if(num < 0) break;
                    powerOfTwo *= 2;
                }
                if (s.charAt(i - 1) == '0') {
                    if(dp[i-1][j] != -1){
                        dp[i][j] = Math.max(dp[i][j], dp[i-1][j] + 1);
                    }
                }
            }
        }

        int maxLength = 0;
        for (int j = 0; j <= k; j++) {
            maxLength = Math.max(maxLength, dp[n][j]);
        }

        return maxLength;
    }
}

