import java.util.Arrays;

public class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);

        int n = buses.length;
        int m = passengers.length;

        int latestTime = -1;

        for (int i = n - 1; i >= 0; i--) {
            int busDepartureTime = buses[i];
            int boardedPassengers = 0;
            int passengerIndex = 0;
            int latestArrivalTimeForBus = -1;

            while (passengerIndex < m && passengers[passengerIndex] <= busDepartureTime && boardedPassengers < capacity) {
                boardedPassengers++;
                latestArrivalTimeForBus = passengers[passengerIndex];
                passengerIndex++;
            }

            if (boardedPassengers > 0) {
                latestTime = Math.max(latestTime, latestArrivalTimeForBus);
            }
        }

        if (latestTime == -1) {
            return 0;
        }

        return latestTime;
    }
}

