            while (passengerIndex < m && passengers[passengerIndex] <= busDepartureTime && passengersOnBus < capacity) {
                passengersOnBus++;
                latestPassengerArrivalTime = passengers[passengerIndex];
                passengerIndex++;
            }

            if (passengersOnBus > 0) {
                if (latestTime == -1) {
                    latestTime = latestPassengerArrivalTime;
                } else {
                    latestTime = Math.max(latestTime, latestPassengerArrivalTime);
