public class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);

        int latestTime = 0;
        int busIndex = buses.length - 1;
        int passengerIndex = passengers.length - 1;

        while (busIndex >= 0 && passengerIndex >= 0) {
            int busDepartureTime = buses[busIndex];
            int passengerArrivalTime = passengers[passengerIndex];

            if (passengerArrivalTime <= busDepartureTime) {
                latestTime = Math.max(latestTime, passengerArrivalTime);
                passengerIndex--;
            } else {
                busIndex--;
            }
        }

        if (busIndex < 0) {
            return buses[0] - 1;
        }

        int busDepartureTime = buses[busIndex];
        int numPassengersOnBus = 0;
        int lastPassengerArrivalTime = 0;

        for (int i = passengers.length - 1; i >= 0; i--) {
            if (passengers[i] <= busDepartureTime) {
                numPassengersOnBus++;
                if (numPassengersOnBus > capacity) {
                    break;
                }
                lastPassengerArrivalTime = passengers[i];
            }
        }

        if (numPassengersOnBus <= capacity) {
            return Math.max(latestTime, busDepartureTime - 1);
        } else {
            return lastPassengerArrivalTime;
        }
    }
}

