public class Solution {
    public TreeNode reverseOddLevels(TreeNode root) {
        if (root == null) {
            return null;
        }

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        int level = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            List<Integer> levelValues = new ArrayList<>();

            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                levelValues.add(node.val);

                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }

            if (level % 2 != 0) {
                int left = 0;
                int right = levelValues.size() - 1;
                while (left < right) {
                    int temp = levelValues.get(left);
                    levelValues.set(left, levelValues.get(right));
                    levelValues.set(right, temp);
                    left++;
                    right--;
                }
            }

            level++;
        }

        return root;
    }
}

