            return null;
        }

        reverseOddLevelsHelper(root, 0);
        return root;
    }

    private void reverseOddLevelsHelper(TreeNode node, int level) {
        if (node == null) {
            return;
        }

        if (level % 2 != 0) {
            reverseOddLevelNodes(getNodeValuesAtLevel(root, level));
        }

        reverseOddLevelsHelper(node.left, level + 1);
        reverseOddLevelsHelper(node.right, level + 1);
    }

    private List<Integer> getNodeValuesAtLevel(TreeNode root, int level) {
        List<Integer> values = new ArrayList<>();
        if (root == null) {
            return values;
        }

        if (level == 0) {
            values.add(root.val);
            return values;
        }

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        int currentLevel = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            if (currentLevel == level) {
                while (size > 0) {
                    TreeNode node = queue.poll();
                    values.add(node.val);
                    size--;
                }
                return values;
            }

            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }
            currentLevel++;
        }
        return values;
    }

    private void reverseOddLevelNodes(List<Integer> values) {
        int left = 0;
        int right = values.size() - 1;
        while (left < right) {
            int temp = values.get(left);
            values.set(left, values.get(right));
            values.set(right, temp);
            left++;
            right--;
        }
    }
}

