     *
     * @param nums1 The first array.
     * @param nums2 The second array.
     * @param diff The difference.
     * @return The number of pairs that satisfy the conditions.
     */
    public int countPairs(int[] nums1, int[] nums2, int diff) {
        int n = nums1.length;
        int count = 0;

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (nums1[i] - nums1[j] <= nums2[i] - nums2[j] + diff) {
                    count++;
                }
            }
        }

        return count;
    }
}

