import java.util.Arrays;

public class Solution {

    public int daysTogether(String arriveAlice, String leaveAlice, String arriveBob, String leaveBob) {
        int startAlice = dateToInt(arriveAlice);
        int endAlice = dateToInt(leaveAlice);
        int startBob = dateToInt(arriveBob);
        int endBob = dateToInt(leaveBob);

        int startTogether = Math.max(startAlice, startBob);
        int endTogether = Math.min(endAlice, endBob);

        if (startTogether <= endTogether) {
            return endTogether - startTogether + 1;
        } else {
            return 0;
        }
    }

    private int dateToInt(String date) {
        String[] parts = date.split("-");
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);

        int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        int totalDays = 0;
        for (int i = 0; i < month - 1; i++) {
            totalDays += daysInMonth[i];
        }
        totalDays += day;
        return totalDays;
    }
}

