// #2022_10_24_Time_31_ms_(95.05%)_Space_52.3_MB_(94.41%)
public class Solution {
    public int[] smallestSubarrays(int[] nums) {
        int n = nums.length;
        int[] answer = new int[n];

        for (int i = 0; i < n; i++) {
            int maxOr = 0;
            for (int j = i; j < n; j++) {
                int currentOr = 0;
                for (int k = i; k <= j; k++) {
                    currentOr |= nums[k];
                }
                maxOr = Math.max(maxOr, currentOr);
            }

            int minLength = Integer.MAX_VALUE;
            for (int j = i; j < n; j++) {
                int currentOr = 0;
                for (int k = i; k <= j; k++) {
                    currentOr |= nums[k];
                }
                if (currentOr == maxOr) {
                    minLength = Math.min(minLength, j - i + 1);
                }
            }
            answer[i] = minLength;
        }

        return answer;
    }
}

