import java.util.PriorityQueue;

public class Solution {
    public long totalCost(int[] costs, int k, int candidates) {
        long totalCost = 0;
        int n = costs.length;
        boolean[] hired = new boolean[n];

        for (int i = 0; i < k; i++) {
            int leftCandidateCount = Math.min(candidates, n - (k - i - 1));
            int rightCandidateCount = Math.min(candidates, k - i);

            PriorityQueue<Integer> leftHeap = new PriorityQueue<>((a, b) -> {
                if (costs[a] != costs[b]) {
                    return costs[a] - costs[b];
                } else {
                    return a - b;
                }
            });

            PriorityQueue<Integer> rightHeap = new PriorityQueue<>((a, b) -> {
                if (costs[a] != costs[b]) {
                    return costs[a] - costs[b];
                } else {
                    return a - b;
                }
            });

            for (int j = 0; j < leftCandidateCount; j++) {
                leftHeap.offer(j);
            }

            for (int j = n - rightCandidateCount; j < n; j++) {
                rightHeap.offer(j);
            }

            int leftCost = Integer.MAX_VALUE;
            int leftIndex = -1;
            if (!leftHeap.isEmpty()) {
                leftCost = costs[leftHeap.peek()];
                leftIndex = leftHeap.peek();
            }

            int rightCost = Integer.MAX_VALUE;
            int rightIndex = -1;
            if (!rightHeap.isEmpty()) {
                rightCost = costs[rightHeap.peek()];
                rightIndex = rightHeap.peek();
            }

            if (leftCost <= rightCost) {
                totalCost += leftCost;
                hired[leftIndex] = true;
                leftHeap.poll();
            } else {
                totalCost += rightCost;
                hired[rightIndex] = true;
                rightHeap.poll();
            }
        }

        return totalCost;
    }
}

