        for (int i = 0; i < creators.length; i++) {
            String creator = creators[i];
            String id = ids[i];
            int view = views[i];

            creatorViews.put(creator, creatorViews.getOrDefault(creator, 0L) + view);

            if (!creatorMaxViewId.containsKey(creator) || views[i] > Integer.parseInt(creatorMaxViewId.get(creator).substring(0, Math.min(creatorMaxViewId.get(creator).length(), 1)))) {
                creatorMaxViewId.put(creator, id);
            } else if (views[i] == Integer.parseInt(creatorMaxViewId.get(creator).substring(0, Math.min(creatorMaxViewId.get(creator).length(), 1)))) {
                if (id.compareTo(creatorMaxViewId.get(creator)) < 0) {
                    creatorMaxViewId.put(creator, id);
                }
            }
        }

        long maxPopularity = 0;
        for (long popularity : creatorViews.values()) {
            maxPopularity = Math.max(maxPopularity, popularity);
        }

        List<List<String>> result = new ArrayList<>();
        for (Map.Entry<String, Long> entry : creatorViews.entrySet()) {
            if (entry.getValue() == maxPopularity) {
                String creator = entry.getKey();
                String id = creatorMaxViewId.get(creator);
                List<String> creatorId = new ArrayList<>();
                creatorId.add(creator);
                creatorId.add(id);
                result.add(creatorId);
            }
        }

        return result;
    }
}

