public class Solution {
    public int destroyTargets(int[] nums, int space) {
        HashMap<Integer, Integer> counts = new HashMap<>();
        for (int num : nums) {
            counts.put(num, counts.getOrDefault(num, 0) + 1);
        }

        int maxDestroyed = 0;
        int minSeed = Integer.MAX_VALUE;

        for (int seed : counts.keySet()) {
            HashSet<Integer> destroyed = new HashSet<>();
            for (int num : nums) {
                if ((num - seed) % space == 0) {
                    destroyed.add(num);
                }
            }
            if (destroyed.size() > maxDestroyed) {
                maxDestroyed = destroyed.size();
                minSeed = seed;
            } else if (destroyed.size() == maxDestroyed && seed < minSeed) {
                minSeed = seed;
            }
        }

        return minSeed;
    }
}

