public class Solution {
    public int pivotInteger(int n) {
        if (n == 1) {
            return 1;
        }

        long totalSum = (long)n * (n + 1) / 2;

        for (int x = 1; x <= n; x++) {
            long leftSum = (long)x * (x + 1) / 2;
            long rightSum = totalSum - leftSum;

            if (leftSum == rightSum) {
                return x;
            }
        }

        return -1;
    }
}

