import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    private int n;
    private List<List<Integer>> adj;
    private int[] amount;
    private boolean[] visited;

    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        this.n = edges.length + 1;
        this.adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        this.amount = amount;
        this.visited = new boolean[n];

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        int maxProfit = Integer.MIN_VALUE;
        for (int leaf : findLeaves()) {
            maxProfit = Math.max(maxProfit, calculateProfit(leaf, bob));
        }

        return maxProfit;
    }

    private List<Integer> findLeaves() {
        List<Integer> leaves = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (adj.get(i).size() == 1) {
                leaves.add(i);
            }
        }
        return leaves;
    }

    private int calculateProfit(int leaf, int bobStart) {
        int profit = 0;
        int current = 0;
        int bobCurrent = bobStart;
        List<Integer> alicePath = new ArrayList<>();
        List<Integer> bobPath = new ArrayList<>();

        // Find Alice's path to the leaf
        findPath(0, leaf, new ArrayList<>(), alicePath);

        // Find Bob's path to node 0
        findPath(bobStart, 0, new ArrayList<>(), bobPath);

        int aliceIndex = 0;
        int bobIndex = 0;

        while (aliceIndex < alicePath.size() && bobIndex < bobPath.size()) {
            int aliceNode = alicePath.get(aliceIndex);
            int bobNode = bobPath.get(bobIndex);

            if (aliceNode == bobNode) {
                if (amount[aliceNode] > 0) {
                    profit += amount[aliceNode] / 2;
                } else {
                    profit -= Math.abs(amount[aliceNode]) / 2;
                }
                aliceIndex++;
                bobIndex++;
            } else if (aliceNode < bobNode) {
                if (amount[aliceNode] > 0) {
                    profit += amount[aliceNode];
                } else {
                    profit -= Math.abs(amount[aliceNode]);
                }
                aliceIndex++;
            } else {
                if (amount[bobNode] > 0) {
                    profit += amount[bobNode];
                } else {
                    profit -= Math.abs(amount[bobNode]);
                }
                bobIndex++;
            }
        }

        while (aliceIndex < alicePath.size()) {
            int aliceNode = alicePath.get(aliceIndex);
            if (amount[aliceNode] > 0) {
                profit += amount[aliceNode];
            } else {
                profit -= Math.abs(amount[aliceNode]);
            }
            aliceIndex++;
        }

        while (bobIndex < bobPath.size()) {
            int bobNode = bobPath.get(bobIndex);
            if (amount[bobNode] > 0) {
                profit += amount[bobNode];
            } else {
                profit -= Math.abs(amount[bobNode]);
            }
            bobIndex++;
        }

        return profit;
    }

    private void findPath(int current, int target, List<Integer> path, List<Integer> result) {
        path.add(current);
        if (current == target) {
            result.addAll(path);
            return;
        }

        for (int neighbor : adj.get(current)) {
            if (!path.contains(neighbor)) {
                findPath(neighbor, target, new ArrayList<>(path), result);
            }
        }
    }
}

