            }
        }

        int maxProfit = Integer.MIN_VALUE;
        for (int leaf : leafNodes) {
            int profit = calculateProfit(adj, amount, 0, leaf, bob);
            maxProfit = Math.max(maxProfit, profit);
        }

        return maxProfit;
