    private int calculateProfit(List<List<Integer>> adj, int[] amount, int aliceNode, int leafNode, int bobNode) {
        int n = amount.length;
        int profit = 0;
        boolean[] visitedAlice = new boolean[n];
        boolean[] visitedBob = new boolean[n];
        List<Integer> pathAlice = new ArrayList<>();
        List<Integer> pathBob = new ArrayList<>();

        findPath(adj, 0, leafNode, visitedAlice, pathAlice);
        findPath(adj, bob, 0, visitedBob, pathBob);

        int i = 0;
        int j = 0;
        while (i < pathAlice.size() && j < pathBob.size()) {
            int aliceNode = pathAlice.get(i);
            int bobNode = pathBob.get(j);

            if (aliceNode == bobNode) {
                if (amount[aliceNode] > 0) {
