public class Solution {
    public int maxPalindromes(String s, int k) {
        int n = s.length();
        if (n < k) {
            return 0;
        }

        int[] dp = new int[n + 1];
        Arrays.fill(dp, 0);

        for (int i = k; i <= n; i++) {
            dp[i] = dp[i - 1];
            for (int j = 1; j <= i - k + 1; j++) {
                int start = i - j;
                int end = i - 1;
                if (isPalindrome(s, start, end)) {
                    dp[i] = Math.max(dp[i], dp[start] + 1);
                }
            }
        }

        return dp[n];
