     * @param cost The array of costs.
     * @return The minimum total cost such that all the elements of the array nums become equal.
     */
    public long minCost(int[] nums, int[] cost) {
        int n = nums.length;
        List<Pair> pairs = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            pairs.add(new Pair(nums[i], cost[i]));
        }

        pairs.sort(Comparator.comparingInt(p -> p.num));

        long totalCost = 0;
        int median = 0;
        long prefixSum = 0;
        for (Pair pair : pairs) {
            prefixSum += pair.cost;
            median = pair.num;
        }

        long bestCost = Long.MAX_VALUE;
        for (int target = 0; target <= 1000; target++) {
            long currentCost = 0;
            for (Pair pair : pairs) {
                currentCost += Math.abs(pair.num - target) * pair.cost;
            }
            bestCost = Math.min(bestCost, currentCost);
        }

        return bestCost;
    }

    private static class Pair {
        int num;
        int cost;

        public Pair(int num, int cost) {
            this.num = num;
            this.cost = cost;
        }
    }
}

