import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;

public class Solution {
    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                if (vals[i] == vals[j]) {
                    List<Integer> path = new ArrayList<>();
                    if (i == j) {
                        path.add(i);
                    } else {
                        path = findPath(adj, i, j, new boolean[n]);
                    }

                    if (path.size() > 0) {
                        boolean isGood = true;
                        for (int k = 0; k < path.size(); k++) {
                            if (vals[path.get(k)] > vals[path.get(0)]) {
                                isGood = false;
                                break;
                            }
                        }
                        if (isGood) {
                            count++;
                        }
                    }
                }
            }
        }

        return count;
    }

    private List<Integer> findPath(List<List<Integer>> adj, int start, int end, boolean[] visited) {
        List<Integer> path = new ArrayList<>();
        visited[start] = true;
        path.add(start);

        if (start == end) {
            return path;
        }

        for (int neighbor : adj.get(start)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                List<Integer> subPath = findPath(adj, neighbor, end, visited);
                if (subPath.size() > 0) {
                    path.addAll(subPath);
                    return path;
                }
            }
        }

        path.clear();
        return path;
    }
}

