public class Solution {
    public int[] productQueries(int n, int[][] queries) {
        List<Integer> powers = new ArrayList<>();
        int temp = n;
        while (temp > 0) {
            if (temp % 2 == 1) {
                powers.add(1);
            }
            temp /= 2;
        }

        long[] prefixProduct = new long[powers.size() + 1];
        prefixProduct[0] = 1;
        for (int i = 0; i < powers.size(); i++) {
            prefixProduct[i + 1] = (prefixProduct[i] * powers.get(i)) % 1000000007;
        }

        int[] answers = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int left = queries[i][0];
            int right = queries[i][1];
            long product = 1;
            if (left == 0) {
                product = prefixProduct[right + 1];
            } else {
                product = (prefixProduct[right + 1] * power(prefixProduct, left, 1000000007)) % 1000000007;
            }
            answers[i] = (int) product;
        }

        return answers;
    }

    private long power(long[] prefixProduct, int left, int mod) {
        long result = 1;
        long base = 1;
        int exponent = left;
        while (exponent > 0) {
            if (exponent % 2 == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exponent /= 2;
        }
