    }

    private long powerMod(long[] arr, int start, int end, int mod) {
        long res = 1;
        for (int i = start; i <= end; i++) {
            res = (res * arr[i]) % mod;
        }
        return res;
    }

    private long power(long base, int exponent, int mod) {
        long res = 1;
        base %= mod;
        while (exponent > 0) {
            if (exponent % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exponent /= 2;
        }
        return res;
    }
}

