public class Solution {
    public long minimumMoney(int[][] transactions) {
        long maxCashback = 0;
        int maxCost = 0;

        for (int[] transaction : transactions) {
            maxCost = Math.max(maxCost, transaction[0]);
            maxCashback = Math.max(maxCashback, (long)transaction[1]);
        }

        long low = 0;
        long high = (long)maxCost * (long)transactions.length;
        long ans = high;

        while (low <= high) {
            long mid = low + (high - low) / 2;
            boolean possible = true;


            for (int i = 0; i < transactions.length; i++) {
                long currentMoney = mid;
                for (int j = 0; j < transactions.length; j++) {
                    if (currentMoney >= transactions[j][0]) {
                        currentMoney -= transactions[j][0];
                        currentMoney += transactions[j][1];
                    } else {
                        possible = false;
                        break;
                    }
                }
                if (!possible) break;
            }

            if (possible) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        return ans;
    }
}

