import java.util.ArrayList;
import java.util.List;

public class Solution {
    public String[] splitMessage(String message, int limit) {
        int n = message.length();
        if (n == 0) {
            return new String[0];
        }

        int minParts = Integer.MAX_VALUE;
        String[] bestParts = new String[0];

        for (int numParts = 1; numParts <= n; numParts++) {
            if (numParts == 1) {
                if (n <= limit) {
                    String part = message + "<" + 1 + "/" + 1 + ">";
                    if (part.length() <= limit) {
                        return new String[]{part};
                    }
                }
                continue;
            }

            int partLength = (int) Math.floor((double) n / numParts);
            int lastPartLength = n - (numParts - 1) * partLength;

            if (partLength * (numParts - 1) + lastPartLength > n) {
                continue;
            }

            if (partLength + 3 > limit && lastPartLength + 3 > limit) {
                continue;
            }

            List<String> parts = new ArrayList<>();
            int start = 0;
            for (int i = 0; i < numParts - 1; i++) {
                int end = start + partLength;
                String part = message.substring(start, end);
                parts.add(part + "<" + (i + 1) + "/" + numParts + ">");
                start = end;
            }

            int lastPartLength = n - start;
            String lastPart = message.substring(start);
            parts.add(lastPart + "<" + numParts + "/" + numParts + ">");

            boolean valid = true;
            for (String part : parts) {
                if (part.length() > limit) {
                    valid = false;
                    break;
                }
            }

            if (valid) {
                if (numParts < minParts) {
                    minParts = numParts;
                    bestParts = parts.toArray(new String[0]);
                }
            }
        }

        if (bestParts.length == 0) {
            return new String[0];
        }

        return bestParts;
    }
}

