        Set<Integer> used = new HashSet<>();
        for (int i = 0; i < n; i++) {
            if (nums1[i] == nums2[i]) {
                int bestSwap = -1;
                int minCost = Integer.MAX_VALUE;
                for (int j = 0; j < n; j++) {
                    if (!used.contains(j) && nums1[i] != nums2[j]) {
                        long currentCost = i + j;
                        if (currentCost < minCost) {
                            minCost = (int) currentCost;
                            bestSwap = j;
                        }
                    }
                }

                if (bestSwap != -1) {
                    cost += minCost;
                    used.add(bestSwap);
                }
            }
        }

        return cost;
    }
}

