            if (i > totalCells || extroverts < 0) continue;

            int placedPeople = i + extroverts;

            maxHappiness = Math.max(maxHappiness, calculateHappiness(m, n, i, extroverts));
        }

        return maxHappiness;
    }

    private int calculateHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        int totalCells = m * n;
        int happiness = 0;

        if (introvertsCount > totalCells || extrovertsCount < 0) return 0;

        int[][] grid = new int[m][n];
        int placedIntroverts = 0;
        int placedExtroverts = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (placedIntroverts < introvertsCount) {
                    grid[i][j] = 2; // Introvert
                    happiness += 120;
                    placedIntroverts++;
                } else if (placedExtroverts < extrovertsCount) {
                    grid[i][j] = 3; // Extrovert
                    happiness += 40;
                    placedExtroverts++;
                } else {
                    grid[i][j] = 0; // Empty
                }
            }
        }

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 2) { // Introvert
                    happiness -= getNeighborHappiness(grid, i, j, 2);
                } else if (grid[i][j] == 3) { // Extrovert
                    happiness += getNeighborHappiness(grid, i, j, 3);
                }
            }
        }

        return happiness;
    }

    private int getNeighborHappiness(int[][] grid, int row, int col, int personType) {
        int happiness = 0;
        int m = grid.length;
        int n = grid[0].length;

        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        for (int[] dir : directions) {
            int newRow = row + dir[0];
            int newCol = col + dir[1];

            if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n) {
                if (grid[newRow][newCol] == 2) {
                    if (personType == 2) happiness -= 30;
                    else happiness += 20;
                } else if (grid[newRow][newCol] == 3) {
                    if (personType == 2) happiness -= 30;
                    else happiness += 20;
                 }
            }
        }
        return happiness;
    }
}

