            int diff = subarray[1] - subarray[0];
            boolean isArithmetic = true;
            for (int j = 2; j < subarray.length; j++) {
                if (subarray[j] - subarray[j - 1] != diff) {
                    isArithmetic = false;
                    break;
                }
            }
            answer.add(isArithmetic);
        }
        return answer;
    }
}

