                    for (int j = 0; j < k; j++) {
                        int newMask = mask | (1 << i);
                        int subset = getSubset(newMask, i, subsetSize);
                        if (isValid(newMask, subset, nums, j)) {
                            int incompatibility = calculateIncompatibility(subset, nums);
                            if (dp[newMask][j + 1] == -1 || dp[newMask][j + 1] > dp[mask][j] + incompatibility) {
                                dp[newMask][j + 1] = dp[mask][j] + incompatibility;
                            }
                        }
                    }
                }
            }
        }

        return dp[(1 << n) - 1][k];
    }

    private int getSubset(int mask, int index, int subsetSize) {
        int subset = 0;
        int count = 0;
        for (int i = 0; i < 10; i++) {
            if ((mask & (1 << (index + i))) != 0) {
                if (count < subsetSize) {
                    subset = subset | (1 << (i));
                    count++;
                }
            }
        }
        return subset;
    }

    private boolean isValid(int mask, int subset, int[] nums, int subsetIndex) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            if ((mask & (1 << i)) != 0) {
                if (getBit(subset, i)) {
                    count++;
                }
            }
        }
        return count == 0;
    }

    private boolean getBit(int subset, int index) {
        return (subset & (1 << index)) != 0;
    }

    private int calculateIncompatibility(int subset, int[] nums) {
        int minVal = Integer.MAX_VALUE;
        int maxVal = Integer.MIN_VALUE;
        for (int i = 0; i < nums.length; i++) {
            if (getBit(subset, i)) {
                minVal = Math.min(minVal, nums[i]);
                maxVal = Math.max(maxVal, nums[i]);
            }
        }
        return maxVal - minVal;
