    public int minIncompatibility(int[] nums, int k) {
        int n = nums.length;
        if (n % k != 0) {
            return -1;
        }

        int subsetSize = n / k;
        Arrays.sort(nums);

        long[][] dp = new long[1 << n][k + 1];
        for (int i = 0; i < (1 << n); i++) {
            Arrays.fill(dp[i], -1);
        }
        dp[0][0] = 0;

        for (int mask = 0; mask < (1 << n); mask++) {
            if (dp[mask][0] == -1) continue;

            for (int subsetIndex = 0; subsetIndex < k; subsetIndex++) {
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) == 0) {
                        int nextMask = mask | (1 << i);
                        long incompatibility = 0;

                        // Calculate incompatibility of the current subset
                        int[] subset = new int[subsetSize];
                        int subsetCount = 0;
                        for (int j = 0; j < n; j++) {
                            if ((mask & (1 << j)) != 0) {
                                subset[subsetCount++] = nums[j];
                                if (subsetCount == subsetSize) break;
                            }
                        }

                        if (subsetCount > 0) {
                            int maxVal = Integer.MIN_VALUE;
                            int minVal = Integer.MAX_VALUE;
                            for (int j = 0; j < subsetCount; j++) {
                                maxVal = Math.max(maxVal, subset[j]);
                                minVal = Math.min(minVal, subset[j]);
                            }
                            incompatibility = (long)maxVal - (long)minVal;
                        }

                        if (dp[nextMask][subsetIndex + 1] == -1) {
                            dp[nextMask][subsetIndex + 1] = dp[mask][subsetIndex] + incompatibility;
