                    values.add(node.val);
                }
            }

            if (level % 2 == 0) { // Even level: odd values in increasing order
                if (!isOddIncreasing(values)) {
                    return false;
                }
            } else { // Odd level: even values in decreasing order
                if (!isEvenDecreasing(values)) {
                    return false;
                }
            }

            List<TreeNode> nextLevelNodes = new ArrayList<>();
            for (TreeNode node : levelNodes) {
                if (node != null) {
                    if (node.left != null) {
                        nextLevelNodes.add(node.left);
                    }
                    if (node.right != null) {
                        nextLevelNodes.add(node.right);
                    }
                }
            }
            levelNodes = nextLevelNodes;
            level++;
        }

        return true;
    }

    private boolean isOddIncreasing(List<Integer> values) {
        if (values.isEmpty()) {
            return true;
        }

        for (int i = 0; i < values.size() - 1; i++) {
            if (values.get(i) % 2 == 0 || values.get(i) >= values.get(i + 1)) {
                return false;
            }
        }
        return true;
    }

    private boolean isEvenDecreasing(List<Integer> values) {
        if (values.isEmpty()) {
            return true;
        }

        for (int i = 0; i < values.size() - 1; i++) {
            if (values.get(i) % 2 != 0 || values.get(i) <= values.get(i + 1)) {
                return false;
            }
        }
        return true;
    }
}

