// #Hard #Array #Dynamic_Programming #Math #Combinatorics
// #2022_04_21_Time_1_ms_(100.00%)_Space_43.3_MB_(20.97%)
public class Solution {
    public String kthSmallestPath(int[] destination, int k) {
        int row = destination[0];
        int col = destination[1];
        StringBuilder path = new StringBuilder();
        int h = 0, v = 0;
        while (h < col || v < row) {
            if (h < col) {
                h++;
                path.append('H');
            } else {
                v++;
                path.append('V');
            }
        }

        if (k == 1) {
            return path.toString();
        }

        return generateKthPath(path.toString(), k);
    }

    private String generateKthPath(String path, int k) {
        int row = 0;
        int col = 0;
        StringBuilder result = new StringBuilder();
        int n = path.length();

        for (int i = 0; i < n; i++) {
            if (path.charAt(i) == 'H') {
                col++;
            } else {
                row++;
            }

            int combinations = combinations(row + col - 1, row);
            if (k <= combinations) {
                result.append('H');
                continue;
            }
            k -= combinations;
            result.append('V');
        }

        return result.toString();
    }

    private long combinations(int n, int k) {
        if (k < 0 || k > n) {
            return 0;
        }
        if (k == 0 || k == n) {
            return 1;
        }
        if (k > n / 2) {
            k = n - k;
        }
        long result = 1;
        for (int i = 1; i <= k; ++i) {
            result = result * (n - i + 1) / i;
        }
        return result;
    }
}

