import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;

        int[][] answer = new int[m][n];
        int[][] flattened = new int[m * n][2];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                flattened[i * n + j][0] = matrix[i][j];
                flattened[i * n + j][1] = i * n + j;
            }
        }

        Arrays.sort(flattened, Comparator.comparingInt(a -> a[0]));

        int rank = 1;
        int prevValue = flattened[0][0];
        flattened[0][1] = rank;

        for (int i = 1; i < m * n; i++) {
            if (flattened[i][0] != prevValue) {
                rank++;
            }
            flattened[i][1] = rank;
            prevValue = flattened[i][0];
        }

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                answer[i][j] = flattened[i * n + j][1];
            }
        }

        return answer;
    }
}

