                flattened[i * n + j][1] = i * n + j;
            }
        }

        Arrays.sort(flattened, (a, b) -> {
            if (a[0] != b[0]) {
                return Integer.compare(a[0], b[0]);
            } else {
                return Integer.compare(a[1], b[1]);
            }
        });

        int rank = 1;
        int prevValue = Integer.MIN_VALUE;
        for (int i = 0; i < m * n; i++) {
            if (flattened[i][0] > prevValue) {
                answer[flattened[i][1] / n][flattened[i][1] % n] = rank;
                prevValue = flattened[i][0];
                rank++;
            } else {
                answer[flattened[i][1] / n][flattened[i][1] % n] = rank - 0;
            }
        }

        return answer;
    }
}

