public class Solution {
    public int numWays(String[] words, String target) {
        int MOD = 1000000007;
        int n = target.length();
        int m = words[0].length();

        // dp[i][j] represents the number of ways to form target[0...i] using the first j words
        long[][] dp = new long[n + 1][words.length + 1];
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= words.length; j++) {
                dp[i][j] = dp[i][j - 1]; // Inherit from the previous word

                for (int k = 0; k < m; k++) {
                    if (target.charAt(i - 1) == words[j - 1].charAt(k)) {
                        dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD;
                    }
                }
            }
        }

        return (int) dp[n][words.length];
    }
}

