import java.util.Map;

public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adj.get(edge[0]).add(edge[1]);
            adj.get(edge[1]).add(edge[0]);
        }

        int[] ans = new int[n - 1];
        for (int d = 1; d < n; d++) {
            ans[d - 1] = countSubtreesWithDiameter(1, -1, adj, d);
        }

        return ans;
    }

    private int countSubtreesWithDiameter(int node, int parent, List<List<Integer>> adj, int diameter) {
        int count = 0;
        List<Integer> children = new ArrayList<>();
        for (int neighbor : adj.get(node)) {
            if (neighbor != parent) {
                children.add(neighbor);
            }
        }

        if (children.isEmpty()) {
            return 1;
        }

        List<Integer> distances = new ArrayList<>();
        for (int child : children) {
            distances.add(getDistance(node, child, adj, new boolean[1001]));
        }

        if (distances.size() == 0) return 1;

        for (int i = 0; i < (1 << children.size()); i++) {
            List<Integer> subtreeNodes = new ArrayList<>();
            subtreeNodes.add(node);
            int subtreeDiameter = 0;
            for (int j = 0; j < children.size(); j++) {
                if ((i >> j) % 2 == 1) {
                    subtreeNodes.add(children.get(j));
                }
            }

            if (subtreeNodes.isEmpty()) continue;

            if (subtreeNodes.size() == 1) {
                if (diameter == 0) {
                    count++;
                }
                continue;
            }

            boolean isSubtree = true;
            for (int subtreeNode : subtreeNodes) {
                for (int otherNode : subtreeNodes) {
                    if (subtreeNode != otherNode) {
                        if (!isConnected(subtreeNode, otherNode, subtreeNodes, adj, new boolean[1001])) {
                            isSubtree = false;
                            break;
                        }
                    }
                }
                if (!isSubtree) break;
            }

            if (isSubtree) {
                int maxDistance = 0;
                for (int u : subtreeNodes) {
                    for (int v : subtreeNodes) {
                        maxDistance = Math.max(maxDistance, getDistance(u, v, adj, new boolean[1001]));
                    }
                }
                if (maxDistance == diameter) {
                    count++;
                }
            }
        }

        return count;
    }

    private int getDistance(int start, int end, List<List<Integer>> adj, boolean[] visited) {
        visited[start] = true;
        if (start == end) {
            return 0;
        }
        int minDistance = Integer.MAX_VALUE;
        for (int neighbor : adj.get(start)) {
            if (!visited[neighbor]) {
                int distance = getDistance(neighbor, end, adj, visited);
                if (distance != -1) {
                    minDistance = Math.min(minDistance, distance + 1);
                }
            }
        }
        visited[start] = false;
        return (minDistance == Integer.MAX_VALUE) ? -1 : minDistance;
    }

    private boolean isConnected(int start, int end, List<Integer> subtreeNodes, List<List<Integer>> adj, boolean[] visited) {
        visited[start] = true;
        if (start == end) {
            return true;
        }
        for (int neighbor : adj.get(start)) {
            if (subtreeNodes.contains(neighbor) && !visited[neighbor]) {
                visited[neighbor] = true;
                if (isConnected(neighbor, end, subtreeNodes, adj, visited)) {
                    return true;
                }
            }
        }
        return false;
    }

    private int count = 0;
}

