            for (int subtreeNode : subtreeNodes) {
                boolean reachable = false;
                for (int otherNode : subtreeNodes) {
                    if (subtreeNode == otherNode) {
                        reachable = true;
                        break;
                    }
                }
                if (!reachable) {
                    isSubtree = false;
                    break;
                }
            }

            if (!isSubtree) continue;

            int maxDistance = 0;
            for (int u : subtreeNodes) {
                for (int v : subtreeNodes) {
                    maxDistance = Math.max(maxDistance, getDistanceBetweenNodes(u, v, subtreeNodes, adj));
                }
            }
            if (maxDistance == diameter) {
                count++;
            }
        }

        return count;
    }

    private int getDistanceBetweenNodes(int startNode, int endNode, List<Integer> subtreeNodes, List<List<Integer>> adj) {
        if (startNode == endNode) return 0;

        boolean[] visited = new boolean[adj.size()];
        return bfs(startNode, endNode, subtreeNodes, adj, visited);
    }

    private int bfs(int startNode, int endNode, List<Integer> subtreeNodes, List<List<Integer>> adj, boolean[] visited) {
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(startNode);
        visited[startNode] = true;
        Map<Integer, Integer> distanceMap = new HashMap<>();
        distanceMap.put(startNode, 0);

        while (!queue.isEmpty()) {
            int currentNode = queue.poll();

            if (currentNode == endNode) {
                return distanceMap.get(currentNode);
            }

            for (int neighbor : adj.get(currentNode)) {
                if (neighbor != -1 && subtreeNodes.contains(neighbor) && !visited[neighbor]) {
                    visited[neighbor] = true;
                    distanceMap.put(neighbor, distanceMap.get(currentNode) + 1);
                    queue.offer(neighbor);
                }
            }
        }

        return -1;
    }

    private int getDistance(int startNode, int endNode, List<List<Integer>> adj, boolean[] visited) {
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(startNode);
        visited[startNode] = true;
        Map<Integer, Integer> distanceMap = new HashMap<>();
        distanceMap.put(startNode, 0);

        while (!queue.isEmpty()) {
            int currentNode = queue.poll();

            if (currentNode == endNode) {
                return distanceMap.get(currentNode);
            }

            for (int neighbor : adj.get(currentNode)) {
                if (!visited[neighbor]) {
                    visited[neighbor] = true;
                    distanceMap.put(neighbor, distanceMap.get(currentNode) + 1);
                    queue.offer(neighbor);
                }
            }
        }

        return -1;
    }
