            String next1 = addA(curr, a);
            if (!visited.contains(next1)) {
                q.offer(next1);
                visited.add(next1);
            }

            // Operation 2: Rotate right by 'b' positions
            String next2 = rotate(curr, b);
            if (!visited.contains(next2)) {
                q.offer(next2);
                visited.add(next2);
            }
        }

        return smallest;
    }

    private String addA(String s, int a) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            int digit = s.charAt(i) - '0';
            if (i % 2 == 0) {
                digit = (digit + a) % 10;
            }
            sb.append(digit);
        }
        return sb.toString();
    }

    private String rotate(String s, int b) {
        b = b % s.length();
        String rotated = s.substring(s.length() - b) + s.substring(0, s.length() - b);
        return rotated;
    }
}

