public class Solution {
    public int concatenatedBinary(int n) {
        long result = 0;
        long mod = 1000000007;

        for (int i = 1; i <= n; i++) {
            int bits = Integer.SIZE - Integer.numberOfLeadingZeros(i);
            result = (result * (1L << bits)) % mod;
            result = (result + i) % mod;
        }

        return (int) result;
    }
}

