import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    public int visiblePoints(List<List<Integer>> points, int angle, List<Integer> location) {
        int n = points.size();
        List<Double> angles = new ArrayList<>();
        for (List<Integer> point : points) {
            int x = point.get(0);
            int y = point.get(1);
            double dx = x - location.get(0);
            double dy = y - location.get(1);
            double angleRad = Math.atan2(dy, dx);
            angles.add(angleRad * 180 / Math.PI);
        }
        Collections.sort(angles);
        int count = 0;
        double maxVisible = 0;
        for (int i = 0; i < n; i++) {
            double currentAngle = angles.get(i);
            double startAngle = currentAngle - angle / 2.0;
            double endAngle = currentAngle + angle / 2.0;
            while (endAngle - startAngle > 360) {
                endAngle -= 360;
            }
            int visibleCount = 0;
            for (int j = 0; j < n; j++) {
                double otherAngle = angles.get(j);
                if (otherAngle >= startAngle && otherAngle <= endAngle) {
                    visibleCount++;
                } else if (otherAngle + 360 >= startAngle && otherAngle + 360 <= endAngle) {
                    visibleCount++;
                }
            }
            maxVisible = Math.max(maxVisible, visibleCount);
        }
        return (int) Math.ceil(maxVisible);
    }
}

