public class Solution {
    public int[] bestCoordinate(int[][] towers, int radius) {
        int[][] grid = new int[1001][1001];
        for (int[] tower : towers) {
            int x = tower[0];
            int y = tower[1];
            int q = tower[2];
            for (int i = 0; i < 1001; i++) {
                for (int j = 0; j < 1001; j++) {
                    double dist = Math.sqrt(Math.pow(i - x, 2) + Math.pow(j - y, 2));
                    if (dist <= radius) {
                        grid[i][j] += q / (1 + (int) Math.ceil(dist));
                    }
                }
            }
        }

        int maxQuality = -1;
        int[] bestCoord = new int[2];

        for (int i = 0; i < 1001; i++) {
            for (int j = 0; j < 1001; j++) {
                if (grid[i][j] > maxQuality) {
                    maxQuality = grid[i][j];
                    bestCoord[0] = i;
                    bestCoord[1] = j;
                } else if (grid[i][j] == maxQuality) {
                    if (i < bestCoord[0]) {
                        bestCoord[0] = i;
                        bestCoord[1] = j;
                    } else if (i == bestCoord[0] && j < bestCoord[1]) {
                        bestCoord[1] = j;
                    }
                }
            }
        }

        return bestCoord;
    }
}

