public class Solution {
    public int getMaximumGenerated(int n) {
        if (n == 0) {
            return 0;
        }

        int[] nums = new int[n + 1];
        nums[0] = 0;
        if (n >= 1) {
            nums[1] = 1;
        }

        for (int i = 2; i <= n; i++) {
            if (2 * i <= n) {
                nums[i] = nums[i / 2];
            } else {
                nums[i] = nums[i / 2] + nums[i / 2 + 1];
            }
        }

        int maxVal = 0;
        for (int i = 0; i <= n; i++) {
            maxVal = Math.max(maxVal, nums[i]);
        }

        return maxVal;
    }
}

