public class Solution {
    public int stoneGameVII(int[] stones) {
        int n = stones.length;
        int[][] dp = new int[n][n];
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + stones[i];
        }

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                int scoreAliceLeft = prefixSum[j + 1] - prefixSum[i + 1] - dp[i + 1][j];
                int scoreAliceRight = prefixSum[j] - prefixSum[i] - dp[i][j - 1];
                dp[i][j] = Math.max(scoreAliceLeft, scoreAliceRight);
            }
        }

        return dp[0][n - 1];
    }
}

