import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;
import java.util.TreeSet;

public class Solution {

    public List<Integer> busiestServers(int[] arrival, int[] load) {
        int k = arrival.length;
        int n = arrival.length;
        int[] serverLoad = new int[k];
        int[] serverRequests = new int[k];

        for (int i = 0; i < n; i++) {
            int serverId = arrival[i] % k;
            if (serverLoad[serverId] == 0) {
                serverLoad[serverId] = load[i];
                serverRequests[serverId]++;
            } else {
                int nextServerId = -1;
                for (int j = 0; j < k; j++) {
                    int next = (serverId + j + 1) % k;
                    if (serverLoad[next] == 0) {
                        nextServerId = next;
                        break;
                    }
                }
                if (nextServerId == -1) {
                    // All servers are busy, drop the request
                    continue;
                } else {
                    serverLoad[nextServerId] = load[i];
                    serverRequests[nextServerId]++;
                }
            }
        }

        int maxRequests = 0;
        for (int requests : serverRequests) {
            maxRequests = Math.max(maxRequests, requests);
        }

        List<Integer> busiestServers = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            if (serverRequests[i] == maxRequests) {
                busiestServers.add(i);
            }
        }

        return busiestServers;
    }
}

