import java.util.Arrays;

public class Solution {
    public int maximumRequests(int n, int[][] requests) {
        int maxRequests = 0;
        int[][] arr = new int[n][2];
        for (int[] request : requests) {
            arr[request[0]][0]++;
            arr[request[1]][1]++;
        }

        int[] in = new int[n];
        int[] out = new int[n];
        for (int i = 0; i < n; i++) {
            in[i] = -arr[i][0];
            out[i] = arr[i][1];
        }

        maxRequests = solve(n, in, out, 0);
        return maxRequests;
    }

    private int solve(int n, int[] in, int[] out, int index) {
        if (index == n) {
            for (int i = 0; i < n; i++) {
                if (in[i] + out[i] != 0) {
                    return 0;
                }
            }
            return 1;
        }

        int maxRequests = 0;
        if (in[index] + out[index] == 0) {
            maxRequests = Math.max(maxRequests, solve(n, in, out, index + 1));
        }

        int requests = 0;
        for (int i = 0; i < n; i++) {
            if (i != index && in[i] > 0 && out[index] > 0 && in[i] + out[index] == 0) {
                int[] tempIn = Arrays.copyOf(in, n);
                int[] tempOut = Arrays.copyOf(out, n);
                tempIn[i]--;
                tempOut[index]--;
                requests = Math.max(requests, 1 + solve(n, tempIn, tempOut, index + 1));
            }
        }

        return Math.max(requests, solve(n, in, out, index + 1));
    }
}

