public class Solution {
    public int maximumRequests(int n, int[][] requests) {
        int maxRequests = 0;
        int[][] permutation = new int[requests.length];
        for (int i = 0; i < requests.length; i++) {
            permutation[i] = i;
        }

        permute(requests, n, permutation, 0, maxRequests);

        return maxRequests;
    }

    private void permute(int[][] requests, int n, int[] permutation, int index, int maxRequests) {
        if (index == requests.length) {
            if (isAchievable(requests, n, permutation)) {
                maxRequests = Math.max(maxRequests, permutation.length);
            }
            return;
        }

        int[] temp = Arrays.copyOf(permutation, permutation.length);
        for (int i = index; i < permutation.length; i++) {
            swap(permutation, index, i);
            permute(requests, n, permutation, index + 1, maxRequests);
            swap(permutation, index, i);
        }
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    private boolean isAchievable(int[][] requests, int n, int[] permutation) {
        int[] buildingChanges = new int[n];
        for (int i = 0; i < requests.length; i++) {
            int from = requests[permutation[i]][0];
            int to = requests[permutation[i]][1];
            buildingChanges[from]--;
            buildingChanges[to]++;
        }

        for (int change : buildingChanges) {
            if (change != 0) {
                return false;
            }
        }

        return true;
    }
}

