public class Solution {
    public int maximumRequests(int n, int[][] requests) {
        int maxRequests = 0;
        int[][] permutation = requests;
        boolean[] used = new boolean[requests.length];
        maxRequests = solve(n, requests, 0, 0, used, maxRequests);
        return maxRequests;
    }

    private int solve(int n, int[][] requests, int index, int currentRequests, boolean[] used, int maxRequests) {
        if (index == requests.length) {
            int[] balance = new int[n];
            for (int i = 0; i < requests.length; i++) {
                if (used[i]) {
                    balance[requests[i][0]]--;
                    balance[requests[i][1]]++;
                }
            }

            boolean possible = true;
            for (int i = 0; i < n; i++) {
                if (balance[i] != 0) {
                    possible = false;
                    break;
                }
            }

            if (possible) {
                return Math.max(maxRequests, currentRequests);
            } else {
                return maxRequests;
            }
        }

        int max = maxRequests;
        // Include the current request
        used[index] = true;
        max = Math.max(max, solve(n, requests, index + 1, currentRequests + 1, used, maxRequests));
        used[index] = false;

        // Exclude the current request
        max = Math.max(max, solve(n, requests, index + 1, currentRequests, used, maxRequests));

        return max;
    }
}

