    public long highestBasketballTeamScore(int[] scores, int[] ages) {
        int n = scores.length;
        if (n == 0) {
            return 0;
        }

        // Create an array of Player objects to store the score and age of each player.
        Player[] players = new Player[n];
        for (int i = 0; i < n; i++) {
            players[i] = new Player(scores[i], ages[i]);
        }

        // Sort the players in ascending order of age.
        Arrays.sort(players, (a, b) -> a.age - b.age);

        // dp[i] stores the maximum score of a team that can be formed using the first i players.
        long[] dp = new long[n];

        // Initialize the first element of the dp array.
        dp[0] = players[0].score;

        // Iterate over the remaining players.
        for (int i = 1; i < n; i++) {
            // Initialize the current element of the dp array to the previous element.
            dp[i] = dp[i - 1];

            // Check if the current player can be added to the team.
            if (players[i].score > players[i - 1].score) {
                dp[i] = Math.max(dp[i], dp[i - 1] + players[i].score);
            } else {
                dp[i] = Math.max(dp[i], players[i].score);
            }
        }

        return dp[n - 1];
    }

    private static class Player {
        int score;
        int age;

        public Player(int score, int age) {
            this.score = score;
            this.age = age;
        }
