import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public List<String> alertNames(String[] keyName, String[] keyTime) {
        Map<String, List<Integer>> nameToTimes = new HashMap<>();
        for (int i = 0; i < keyName.length; i++) {
            String name = keyName[i];
            int time = parseTime(keyTime[i]);
            nameToTimes.computeIfAbsent(name, k -> new ArrayList<>()).add(time);
        }

        List<String> alertedNames = new ArrayList<>();
        for (Map.Entry<String, List<Integer>> entry : nameToTimes.entrySet()) {
            String name = entry.getKey();
            List<Integer> times = entry.getValue();
            Collections.sort(times);

            for (int i = 0; i < times.size() - 2; i++) {
                if (times.get(i + 2) - times.get(i) < 3600) {
                    alertedNames.add(name);
                    break;
                }
            }
        }

        Collections.sort(alertedNames);
        return alertedNames;
    }

    private int parseTime(String time) {
        String[] parts = time.split(":");
        int hour = Integer.parseInt(parts[0]);
        int minute = Integer.parseInt(parts[1]);
        return hour * 60 + minute;
    }
}

