public class Solution {
    public List<String> alertNames(String[] keyName, String[] keyTime) {
        Map<String, List<Integer>> nameToTimes = new HashMap<>();
        for (int i = 0; i < keyName.length; i++) {
            String name = keyName[i];
            int time = parseTime(keyTime[i]);
            nameToTimes.computeIfAbsent(name, k -> new ArrayList<>()).add(time);
        }

        List<String> alertedNames = new ArrayList<>();
        for (Map.Entry<String, List<Integer>> entry : nameToTimes.entrySet()) {
