                }
            }
        }

        Collections.sort(alertedNames);
        return alertedNames;
    }

    private int parseTime(String time) {
        String[] parts = time.split(":");
        int hour = Integer.parseInt(parts[0]);
        int minute = Integer.parseInt(parts[1]);
        return hour * 60 + minute;
    }
}

