public class Solution {
    public int maxHeight(int[][] arr) {
        int n = arr.length;
        int[] dp = new int[n];

        // Sort cuboids based on their base area (width * length) in ascending order
        Arrays.sort(arr, (a, b) -> (a[0] * a[1]) - (b[0] * b[1]));

        for (int i = 0; i < n; i++) {
            dp[i] = arr[i][2]; // Initialize with the height of the current cuboid
            for (int j = 0; j < i; j++) {
                if (arr[i][0] <= arr[j][0] && arr[i][1] <= arr[j][1] && arr[i][2] <= arr[j][2]) {
                    dp[i] = Math.max(dp[i], dp[j] + arr[i][2]);
                }
            }
        }

        int maxHeight = 0;
        for (int height : dp) {
            maxHeight = Math.max(maxHeight, height);
        }

        return maxHeight;
    }
}

