import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public int maxHeight(int[][] arr) {
        int n = arr.length;
        if (n == 0) {
            return 0;
        }

        // Sort cuboids based on width, length, and height
        Arrays.sort(arr, (a, b) -> {
            if (a[0] != b[0]) {
                return a[0] - b[0];
            }
            if (a[1] != b[1]) {
                return a[1] - b[1];
            }
            return a[2] - b[2];
        });

        // dp[i] stores the maximum height achievable with cuboid i at the top
        int[] dp = new int[n];
        for (int i = 0; i < n; i++) {
            dp[i] = arr[i][2]; // Initialize with the height of the cuboid itself
        }

        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (arr[i][0] <= arr[j][0] && arr[i][1] <= arr[j][1] && arr[i][2] <= arr[j][2]) {
                    dp[i] = Math.max(dp[i], dp[j] + arr[i][2]);
                }
            }
        }

        int maxHeight = 0;
        for (int height : dp) {
            maxHeight = Math.max(maxHeight, height);
        }

        return maxHeight;
    }
}

