                if (len - i == 1) {
                    result.append(digits.substring(i));
                } else {
                    result.append(digits.substring(i, i + 2));
                }
                break;
            }
        }

        if (result.length() > 0 && result.charAt(result.length() - 1) == '-') {
            result.deleteCharAt(result.length() - 1);
        }

        return result.toString();
    }
}

