public class Solution {
    public int maximalNetworkRank(int n, int[][] roads) {
        List<Integer>[] adj = new List[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int[] road : roads) {
            int u = road[0] - 1;
            int v = road[1] - 1;
            adj[u].add(v);
            adj[v].add(u);
        }

        int maxRank = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int rank = adj[i].size() + adj[j].size();
                for (int neighbor : adj[i]) {
                    if (neighbor == j) {
                        rank--;
                    }
                }
                maxRank = Math.max(maxRank, rank);
            }
        }

        return maxRank;
    }
}

