        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int rank = 0;
                if (graph[i][j] == 1) {
                    rank++;
                }
                for (int k = 0; k < n; k++) {
                    if (k != i && graph[i][k] == 1) {
                        rank++;
                    }
                    if (k != j && graph[j][k] == 1) {
                        rank++;
                    }
                }
                maxRank = Math.max(maxRank, rank);
            }
        }
        return maxRank;
    }
