public class Solution {
    public int[] maxSumOfThreeSubarrays(int[] nums, int k) {
        int n = nums.length;
        int[] sum = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            sum[i] = sum[i - 1] + nums[i - 1];
        }

        int[] left = new int[n];
        int best = 0;
        for (int i = k; i <= n; i++) {
            if (sum[i] - sum[i - k] > sum[best] - sum[best - k]) {
                best = i - k;
            }
            left[i - 1] = best;
        }

        int[] right = new int[n];
        best = 0;
        for (int i = n - k; i >= 0; i--) {
            if (sum[i + k] - sum[i] > sum[best + k] - sum[best]) {
                best = i;
            }
            right[i] = best;
        }

