import java.util.Arrays;

public class Solution {
    public boolean solve(int[] cards) {
        Arrays.sort(cards);
        return solveHelper(cards, 0, 24);
    }

    private boolean solveHelper(int[] cards, int index, double target) {
        if (index == cards.length - 1) {
            return Math.abs(cards[index] - target) < 1e-6;
        }

        for (int i = index + 1; i < cards.length; i++) {
            double[] newCards = new double[cards.length - 1];
            for (int j = 0; j < index; j++) {
                newCards[j] = cards[j];
            }
            for (int j = index; j < i; j++) {
                newCards[j] = cards[j];
            }
            newCards[i - index - 1] = (double) cards[index] + (double) cards[i];
            if (solveHelper(newCards, index + 1, target)) {
                return true;
            }
            newCards[i - index - 1] = (double) cards[index] - (double) cards[i];
            if (solveHelper(newCards, index + 1, target)) {
                return true;
            }
            newCards[i - index - 1] = (double) cards[index] * (double) cards[i];
            if (solveHelper(newCards, index + 1, target)) {
                return true;
            }
            if (cards[i] != 0) {
                newCards[i - index - 1] = (double) cards[index] / (double) cards[i];
                if (solveHelper(newCards, index + 1, target)) {
                    return true;
                }
            }
        }
        return false;
    }
}

