import java.util.Arrays;

public class Solution {
    public boolean solve(int[] cards) {
        if (cards == null || cards.length != 4) {
            return false;
        }
        Arrays.sort(cards);
        return solveHelper(cards, 0, 24);
    }

    private boolean solveHelper(int[] cards, int index, double target) {
        if (index == cards.length) {
            return false;
        }

        if (index == cards.length - 1) {
            return Math.abs(cards[index] - target) < 1e-6;
        }

        for (int i = index + 1; i < cards.length; i++) {
            // Try all possible operations between cards[index] and cards[i]
            double[] nextCards = new double[cards.length - 1];
            nextCards[0] = cards[index];
            nextCards[1] = cards[i];

            // +
            if (solveWithOperation(nextCards, 2, target, '+')) return true;

            // -
            if (solveWithOperation(nextCards, 2, target, '-')) return true;

            // *
            if (solveWithOperation(nextCards, 2, target, '*')) return true;

            // /
            if (solveWithOperation(nextCards, 2, target, '/')) return true;
        }

        return false;
    }

    private boolean solveWithOperation(double[] nextCards, int index, double target, char op) {
        if (index == nextCards.length) {
            return Math.abs(nextCards[index - 1] - target) < 1e-6;
        }

        if (index == nextCards.length - 1) {
            double result;
            if (op == '+') {
                result = nextCards[0] + nextCards[1] + nextCards[2];
            } else if (op == '-') {
                result = nextCards[0] + nextCards[1] - nextCards[2];
            } else if (op == '*') {
                result = nextCards[0] * nextCards[1] * nextCards[2];
            } else {
                result = (nextCards[0] * nextCards[1]) / nextCards[2];
            }
            return Math.abs(result - target) < 1e-6;
        }

        double[] nextCards = new double[nextCards.length - 1];
        double result;
        if (op == '+') {
            result = nextCards[0] + nextCards[1];
        } else if (op == '-') {
            result = nextCards[0] - nextCards[1];
        } else if (op == '*') {
            result = nextCards[0] * nextCards[1];
        } else {
            result = (nextCards[0]) / nextCards[1];
        }

        nextCards[0] = result;
        return solveHelper(nextCards, index + 1, target);
    }
}

