            double[] operators = {1.0, -1.0, 2.0, 1.0 / 2.0};

            for (double operator : operators) {
                double result = operator * (double) cards[index] + (double) cards[i];

                if (Math.abs(result - target) < 1e-6) {
                    return true;
                }

                if (solveHelper(cards, i, target - result)) {
                    return true;
                }
            }
        }

        return false;
