import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public List<List<String>> findDuplicate(String[] paths) {
        Map<String, List<String>> contentToFilePaths = new HashMap<>();
        for (String path : paths) {
            String[] parts = path.split(" ");
            String directory = parts[0];
            for (int i = 1; i < parts.length; i++) {
                String[] fileInfo = parts[i].split("\\(");
                String fileName = fileInfo[0];
                String content = fileInfo[1].substring(0, fileInfo[1].length() - 1);

                String filePath = directory + "/" + fileName;
                contentToFilePaths.computeIfAbsent(content, k -> new ArrayList<>()).add(filePath);
            }
        }

        List<List<String>> duplicateFiles = new ArrayList<>();
        for (List<String> filePaths : contentToFilePaths.values()) {
            if (filePaths.size() >= 2) {
                duplicateFiles.add(filePaths);
            }
        }

        return duplicateFiles;
    }
}

