public class Solution {
    public int minSteps(int n) {
        if (n == 1) {
            return 0;
        }

        int steps = 0;
        int current = 1;

        while (current < n) {
            if (n % 2 == 0) {
                n /= 2;
                steps++;
            } else {
                n--;
                steps++;
            }
        }

        return steps;
    }
}

