import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int scheduleCourse(int[][] courses) {
        // Sort the courses based on their deadline date.
        Arrays.sort(courses, (a, b) -> a[1] - b[1]);

        // Use a max heap to store the durations of the courses taken so far.
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);

        int currentTime = 0;
        for (int[] course : courses) {
            int duration = course[0];
            int lastDay = course[1];

            if (currentTime + duration <= lastDay) {
                currentTime += duration;
                pq.offer(duration);
            } else if (!pq.isEmpty() && duration < pq.peek()) {
                // If the current course's duration is less than the longest course taken so far,
                // we can replace the longest course with the current course.
                currentTime += duration - pq.peek();
                pq.poll();
                pq.offer(duration);
            }
        }

        return pq.size();
    }
}

