        int[] dr = {-2, -2, -1, -1, 1, 1, 2, 2};
        int[] dc = {-1, 1, -2, 2, -2, 2, -1, 1};

        for (int moves = 1; moves <= k; moves++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    for (int l = 0; l < 8; l++) {
                        int newRow = i + dr[l];
                        int newCol = j + dc[l];
                        if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n) {
                            dp[moves][newRow * n + newCol] += dp[moves - 1][i * n + j] / 8.0;
                        }
                    }
                }
            }
        }

        double result = 0.0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                result += dp[k][i * n + j];
            }
        }

        return result;
    }
}

