import java.util.List;
import java.util.Objects;
import java.util.PriorityQueue;

public class Solution {

    public int[] findSmallestRange(List<List<Integer>> nums) {
        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> a.val - b.val);
        int maxVal = Integer.MIN_VALUE;
        int rangeStart = 0;
        int rangeEnd = Integer.MAX_VALUE;

        for (int i = 0; i < nums.size(); i++) {
            pq.offer(new Node(nums.get(i).get(0), i, 0));
            maxVal = Math.max(maxVal, nums.get(i).get(0));
        }

        while (pq.size() == nums.size()) {
            Node minNode = pq.poll();
            int currentRange = maxVal - minNode.val;

            if (currentRange < rangeEnd - rangeStart) {
                rangeStart = minNode.val;
                rangeEnd = maxVal;
            } else if (currentRange == rangeEnd - rangeStart) {
                if (minNode.val < rangeStart) {
                    rangeStart = minNode.val;
                }
            }

            int nextIndex = minNode.indexInList + 1;
            if (nextIndex < nums.get(minNode.listIndex).size()) {
                int nextVal = nums.get(minNode.listIndex).get(nextIndex);
                pq.offer(new Node(nextVal, minNode.listIndex, nextIndex));
                maxVal = Math.max(maxVal, nextVal);
            } else {
                break;
            }
        }

        return new int[]{rangeStart, rangeEnd};
    }

    private static class Node {
        int val;
        int listIndex;
        int indexInList;

        public Node(int val, int listIndex, int indexInList) {
            this.val = val;
            this.listIndex = listIndex;
            this.indexInList = indexInList;
        }
    }
}

