                    int cost = offerPrice;
                    if (remainingNeeds > 0) {
                        cost += minimumCostHelper(price, needs, special, i, remainingNeeds);
                    }
                    dp[n] = Math.min(dp[n], cost);
                }
            }
        }

        return dp[n];
    }

