        int n = price.length;
        long[][] dp = new long[1 << n][n + 1];

        for (int i = 0; i < (1 << n); i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = -1;
            }
        }

        return (int) solve(needs, price, special, 0, 0, dp);
    }

    private long solve(int[] needs, int[] price, int[][] special, int mask, int index, long[][] dp) {
        if (index == needs.length) {
            return 0;
        }

        if (dp[mask][index] != -1) {
            return dp[mask][index];
        }

        long ans = Long.MAX_VALUE;

        // Option 1: Buy the item at its regular price
        if (needs[index] > 0) {
            long cost = (long) price[index] * needs[index];
            ans = Math.min(ans, cost + solve(needs, price, special, mask, index + 1, dp));
        }

        // Option 2: Use special offers
        for (int[] offer : special) {
            int offerMask = 0;
            for (int i = 0; i < offer.length - 1; i++) {
                if (offer[i] > 0) {
                    offerMask |= (1 << i);
                }
            }

            if ((offerMask & mask) == offerMask) {
                int buyCount = Math.min(needs[index], offer[index]);
                if(buyCount > 0) {
                    int[] newNeeds = needs.clone();
                    newNeeds[index] -= buyCount;
                    long cost = offer[offer.length - 1] * buyCount;
                    ans = Math.min(ans, cost + solve(newNeeds, price, special, mask, index + 1, dp));
                }
            }
        }

        dp[mask][index] = ans;
        return ans;
    }
}

