    public int longestUnivaluePath(TreeNode root) {
        dfs(root);
        return maxLen;
    }

    private int dfs(TreeNode node) {
        if (node == null) {
            return 0;
        }

        int leftLen = dfs(node.left);
        int rightLen = dfs(node.right);

        int currentLen = 1;
        int leftPath = 0;
        int rightPath = 0;

        if (node.left != null && node.left.val == node.val) {
            leftPath = 1 + leftPath(node.left);
        }
        if (node.right != null && node.right.val == node.val) {
            rightPath = 1 + rightPath(node.right);
        }

        maxLen = Math.max(maxLen, leftPath + rightPath);

        return Math.max(leftPath, rightPath);
    }

    private int leftPath(TreeNode node) {
        if (node == null) {
            return 0;
        }
        if (node.left == null && node.right == null) {
            return 0;
        }

        if (node.left != null && node.left.val == node.val) {
            return 1 + leftPath(node.left);
        } else if (node.right != null && node.right.val == node.val) {
            return 1 + leftPath(node.right);
        } else {
            return 0;
        }
    }

    private int rightPath(TreeNode node) {
        if (node == null) {
            return 0;
        }
        if (node.left == null && node.right == null) {
            return 0;
        }

        if (node.left != null && node.left.val == node.val) {
            return 1 + rightPath(node.left);
        } else if (node.right != null && node.right.val == node.val) {
            return 1 + rightPath(node.right);
        } else {
