public class Solution {
    public int findPeakElement(int[] nums) {
        int start = 0;
        int end = nums.length - 1;

        while (start < end) {
            int mid = start + (end - start) / 2;

            if (nums[mid] > nums[mid + 1]) {
                // We are in a decreasing sequence, so a peak must be on the left
                end = mid;
            } else {
                // We are in an increasing sequence, so a peak must be on the right
                start = mid + 1;
            }
        }

        // At the end of the loop, start == end, and this is the peak element
        return start;
    }
}

