import java.util.HashSet;
import java.util.LinkedList;
import java.util.List;
import java.util.Set;

public class Solution {
    public List<String> wordBreak(String s, List<String> wordDict) {
        Set<String> wordSet = new HashSet<>(wordDict);
        return wordBreakHelper(s, wordSet, "");
    }

    private List<String> wordBreakHelper(String s, Set<String> wordSet, String currentSentence) {
        List<String> result = new LinkedList<>();

        if (s.isEmpty()) {
            result.add(currentSentence.trim());
            return result;
        }

        for (int i = 1; i <= s.length(); i++) {
            String prefix = s.substring(0, i);
            if (wordSet.contains(prefix)) {
                List<String> suffixes = wordBreakHelper(s.substring(i), wordSet, currentSentence + prefix + " ");
                result.addAll(suffixes);
            }
        }

        return result;
    }
}

