import java.util.Arrays;

public class Solution {
    public ListNode insertionSortList(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }

        ListNode sortedHead = head;
        ListNode current = head.next;

        while (current != null) {
            ListNode next = current.next;
            insertNode(sortedHead, current);
            current = next;
        }

        return sortedHead;
    }

    private void insertNode(ListNode sortedHead, ListNode nodeToInsert) {
        if (nodeToInsert.val < sortedHead.val) {
            nodeToInsert.next = sortedHead;
            sortedHead = nodeToInsert;
            return;
        }

        ListNode current = sortedHead;
        while (current.next != null && current.next.val < nodeToInsert.val) {
            current = current.next;
        }

        nodeToInsert.next = current.next;
        current.next = nodeToInsert;
    }
}

