            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.remove(0);
                rightmostNode = node;

                if (node.left != null) {
                    queue.add(node.left);
                }
                if (node.right != null) {
                    queue.add(node.right);
                }
            }
            result.add(rightmostNode.val);
        }
        return result;
    }
}

