// Definition for a Node.
public class Solution {
    public Node connect(Node root) {
        if (root == null) {
            return null;
        }

        // Start with the root node
        Node current = root;

        // Iterate through the tree level by level
        while (current != null) {
            Node nextLevelStart = null;
            Node prev = null;

            // Iterate through the current level
            Node temp = current;
            while (temp != null) {
                // Connect the next pointer of the left child
                if (temp.left != null) {
                    if (prev == null) {
                        nextLevelStart = temp.left;
                    } else {
                        prev.next = temp.left;
                    }
                    prev = temp.left;
                }

                // Connect the next pointer of the right child
                if (temp.right != null) {
                    if (prev == null) {
                        nextLevelStart = temp.right;
                    } else {
                        prev.next = temp.right;
                    }
                    prev = temp.right;
                }

                temp = temp.next;
            }

            // Move to the next level
            current = nextLevelStart;
        }

        return root;
    }
}

