import java.util.Stack;
public class Solution {
    public int evalRPN(String[] tokens) {
        Stack<Integer> stack = new Stack<>();
        for (String token : tokens) {
            switch (token) {
                case "+":
                    int operand2 = stack.pop();
                    int operand1 = stack.pop();
                    stack.push(operand1 + operand2);
                    break;
                case "-":
                    int operand2_minus = stack.pop();
                    int operand1_minus = stack.pop();
                    stack.push(operand1_minus - operand2_minus);
                    break;
                case "*":
                    int operand2_mult = stack.pop();
                    int operand1_mult = stack.pop();
                    stack.push(operand1_mult * operand2_mult);
                    break;
                case "/":
                    int operand2_div = stack.pop();
                    int operand1_div = stack.pop();
                    stack.push(operand1_div / operand2_div);
                    break;
                default:
                    stack.push(Integer.parseInt(token));
                    break;
            }
        }
        return stack.pop();
    }
}

