        if (numerator == 0) {
            return "0";
        }

        StringBuilder sb = new StringBuilder();
        if ((numerator < 0) ^ (denominator < 0)) {
            sb.append("-");
        }

        long num = Math.abs((long) numerator);
        long den = Math.abs((long) denominator);

        sb.append(num / den);
        long rem = num % den;

        if (rem == 0) {
            return sb.toString();
        }

        sb.append(".");
        Map<Long, Integer> remainderMap = new HashMap<>();
        int index = 0;

        while (rem != 0) {
            if (remainderMap.containsKey(rem)) {
                int startIndex = remainderMap.get(rem);
                sb.insert(startIndex, "(");
                sb.append(")");
                break;
            }

            remainderMap.put(rem, index);
            rem *= 10;
            sb.append(rem / den);
            rem %= den;
            index++;
        }

        return sb.toString();
    }
}

