                if (arr1[i - 1] > (j == 0 ? Integer.MIN_VALUE : arr2[j - 1])) {
                    dp[i][j] = Math.min(dp[i][j], dp[i - 1][j]);
                }

                // Option 2: Replace arr1[i-1] with arr2[k]
                for (int k = 0; k <= m; k++) {
                    if (k == 0) {
                        if (arr1[i - 1] > Integer.MIN_VALUE) {
                            dp[i][k] = Math.min(dp[i][k], dp[i - 1][j] + 1);
                        }
                    } else {
                        if (arr1[i - 1] < arr2[k - 1]) {
                            dp[i][k] = Math.min(dp[i][k], dp[i - 1][j] + 1);
                        }
                    }
                }
            }
        }

        long ans = Integer.MAX_VALUE;
        for (int j = 0; j <= m; j++) {
            ans = Math.min(ans, dp[n - 1][j]);
        }

        return (ans == Integer.MAX_VALUE) ? -1 : (int) ans;
    }
}

