import java.util.Arrays;

public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        int n = arr1.length;
        int[] dp = new int[n];
        Arrays.fill(dp, -1);
        arr2 = Arrays.stream(arr2).distinct().sorted().toArray();
        return solve(arr1, arr2, 0, -1, dp);
    }

    private int solve(int[] arr1, int[] arr2, int index, int prev, int[] dp) {
        if (index == arr1.length) {
            return 0;
        }

        if (dp[index] != -1) {
            return dp[index];
        }

        int ans = Integer.MAX_VALUE;

        // Option 1: Don't replace arr1[index]
        if (arr1[index] > prev) {
            int res = solve(arr1, arr2, index + 1, arr1[index], dp);
            if (res != Integer.MAX_VALUE) {
                ans = Math.min(ans, res);
            }
        }

        // Option 2: Replace arr1[index] with a value from arr2
        for (int i = 0; i < arr2.length; i++) {
            if (arr2[i] > prev) {
                int res = solve(arr1, arr2, index + 1, arr2[i], dp);
                if (res != Integer.MAX_VALUE) {
                    ans = Math.min(ans, res + 1);
                }
            }
        }

        dp[index] = ans;
        return ans;
    }
}

