import java.util.Arrays;

public class Solution {
    public int movesToMakeZigzag(int[] nums) {
        int n = nums.length;
        int[] moves1 = new int[n];
        int[] moves2 = new int[n];

        // Calculate moves for even-indexed greater
        for (int i = 0; i < n; i++) {
            if (i % 2 == 0) {
                int left = (i > 0) ? nums[i - 1] : Integer.MIN_VALUE;
                int right = (i < n - 1) ? nums[i + 1] : Integer.MIN_VALUE;
                moves1[i] = Math.max(0, nums[i] - Math.max(left, right) + 1);
            } else {
                moves1[i] = 0;
            }
        }

        // Calculate moves for odd-indexed greater
        for (int i = 0; i < n; i++) {
            if (i % 2 != 0) {
                int left = (i > 0) ? nums[i - 1] : Integer.MIN_VALUE;
                int right = (i < n - 1) ? nums[i + 1] : Integer.MIN_VALUE;
                moves2[i] = Math.max(0, nums[i] - Math.max(left, right) + 1);
            } else {
                moves2[i] = 0;
            }
        }

        int sum1 = 0;
        for (int move : moves1) {
            sum1 += move;
        }

        int sum2 = 0;
        for (int move : moves2) {
            sum2 += move;
        }

        return Math.min(sum1, sum2);
    }
}

