import com_github_leetcode.TreeNode;

public class Solution {
    public boolean btreeGameWinningMove(TreeNode root, int n, int x) {
        if (n == 1) {
            return false;
        }

        for (int y = 1; y <= n; ++y) {
            if (y != x) {
                if (canWin(root, x, y, n)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean canWin(TreeNode root, int x, int y, int n) {
        if (n == 1) {
            return false;
        }

        int redCount = 0;
        int blueCount = 0;
        boolean[] visited = new boolean[n + 1];

        redCount = dfs(root, x, visited);
        blueCount = dfs(root, y, visited);

        return blueCount >= redCount;
    }

    private int dfs(TreeNode root, int target, boolean[] visited) {
        if (root == null) {
            return 0;
        }

        if (visited[root.val]) {
            return 0;
        }

        visited[root.val] = true;

        int count = 0;
        if (root.val == target) {
            count = 1;
        }

        count += dfs(root.left, target, visited);
        count += dfs(root.right, target, visited);

        return count;
    }
}

