import com_github_leetcode.TreeNode;

public class Solution {
    public boolean btreeGameWinningMove(TreeNode root, int n, int x) {
        if (n <= 0 || x <= 0 || x > n) {
            return false;
        }

        for (int y = 1; y <= n; ++y) {
            if (y != x) {
                if (canWin(root, x, y, n)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean canWin(TreeNode root, int x, int y, int n) {
        if (root == null) {
            return false;
        }

        boolean[] redNodes = new boolean[n + 1];
        boolean[] blueNodes = new boolean[n + 1];
        redNodes[x] = true;
        blueNodes[y] = true;

        return solve(root, redNodes, blueNodes, true);
    }

    private boolean solve(TreeNode node, boolean[] redNodes, boolean[] blueNodes, boolean player1Turn) {
        if (node == null) {
            return true;
        }

        if (isGameOver(redNodes, blueNodes)) {
            int redCount = 0;
            for (int i = 1; i <= redNodes.length - 1; i++) {
                if (redNodes[i]) {
                    redCount++;
                }
            }
            int blueCount = 0;
            for (int i = 1; i <= blueNodes.length - 1; i++) {
                if (blueNodes[i]) {
                    blueCount++;
                }
            }
            return blueNodes.length - 1 > redCount;
        }

        if (player1Turn) {
            // Player 1's turn (red)
            if (canMove(node, redNodes, blueNodes, true)) {
                return false;
            } else {
                return true;
            }
        } else {
            // Player 2's turn (blue)
            if (canMove(node, redNodes, blueNodes, false)) {
                return false;
            } else {
                return true;
            }
        }
    }

    private boolean canMove(TreeNode node, boolean[] redNodes, boolean[] blueNodes, boolean player1Turn) {
        if (player1Turn) {
            // Player 1 (red)
            if (node.left != null && !redNodes[node.left.val] && !blueNodes[node.left.val]) {
                redNodes[node.left.val] = true;
                return true;
            }
            if (node.right != null && !redNodes[node.right.val] && !blueNodes[node.right.val]) {
                redNodes[node.right.val] = true;
                return true;
            }
            if (node.parent != null && !redNodes[node.parent.val] && !blueNodes[node.parent.val]) {
                redNodes[node.parent.val] = true;
                return true;
            }
            return false;
        } else {
            // Player 2 (blue)
            if (node.left != null && !redNodes[node.left.val] && !blueNodes[node.left.val]) {
                blueNodes[node.left.val] = true;
                return true;
            }
            if (node.right != null && !redNodes[node.right.val] && !blueNodes[node.right.val]) {
                blueNodes[node.right.val] = true;
                return true;
            }
            if (node.parent != null && !redNodes[node.parent.val] && !blueNodes[node.parent.val]) {
                blueNodes[node.parent.val] = true;
                return true;
            }
            return false;
        }
    }

    private boolean isGameOver(boolean[] redNodes, boolean[] blueNodes) {
        for (int i = 1; i < redNodes.length; i++) {
            if (!redNodes[i]) {
                break;
            }
        }
        for (int i = 1; i < blueNodes.length; i++) {
            if (!blueNodes[i]) {
                break;
            }
        }

        boolean allRedColored = true;
        for (int i = 1; i < redNodes.length; i++) {
            if (!redNodes[i]) {
                allRedColored = false;
                break;
            }
        }

        boolean allBlueColored = true;
        for (int i = 1; i < blueNodes.length; i++) {
            if (!blueNodes[i]) {
                allBlueColored = false;
                break;
            }
        }

        return allRedColored && allBlueColored;
    }
}

