import com_github_leetcode.TreeNode;

public class Solution {
    public boolean btreeGameWinningMove(TreeNode root, int n, int x) {
        if (n <= 0) {
            return false;
        }

        if (x < 1 || x > n) {
            return false;
        }

        for (int y = 1; y <= n; ++y) {
            if (y != x) {
                if (canWin(root, x, y, n)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean canWin(TreeNode root, int x, int y, int n) {
        if (root == null) {
            return false;
        }

        boolean[] visited = new boolean[n + 1];
        int redCount = 0;
        int blueCount = 0;

        // Find the red node
        TreeNode redNode = findNode(root, x);

        // Find the blue node
        TreeNode blueNode = findNode(root, y);

        if (redNode == null || blueNode == null) {
            return false;
        }

        // Simulate the game
        boolean player1Turn = true;
        while (true) {
            TreeNode current;
            if (player1Turn) {
                current = redNode;
            } else {
                current = blueNode;
            }

            if (current == null) {
                break;
            }

            // Find a valid neighbor to color
            TreeNode neighbor = null;
            if (current.left != null && !visited[current.left.val]) {
                neighbor = current.left;
            } else if (current.right != null && !visited[current.right.val]) {
                neighbor = current.right;
            } else if (current.val != 0 && !visited[current.val]) {
                // Find parent
                TreeNode parent = findParent(root, current.val);
                if (parent != null && !visited[parent.val]) {
                    neighbor = parent;
                }
            }

            if (neighbor != null) {
                visited[neighbor.val] = true;
                if (player1Turn) {
                    redCount++;
                } else {
                    blueCount++;
                }
                player1Turn = !player1Turn;
            } else {
                break; // Pass
            }
        }

        return blueCount > redCount;
    }

    private TreeNode findNode(TreeNode root, int val) {
        if (root == null) {
            return null;
        }
        if (root.val == val) {
            return root;
        }
        TreeNode left = findNode(root.left, val);
        if (left != null) {
            return left;
        }
        return findNode(root.right, val);
    }

    private TreeNode findParent(TreeNode root, int val) {
        if (root == null || root.val == val) {
            return null;
        }

        if (root.left != null && root.left.val == val) {
            return root;
        }

        if (root.right != null && root.right.val == val) {
            return root;
        }

        TreeNode left = findParent(root.left, val);
        if (left != null) {
            return left;
        }

        return findParent(root.right, val);
    }
}

