                int j = i + len - 1;
                dp[i][j] = Integer.MAX_VALUE;
                for (int k = i; k < j; k++) {
                    int leftMax = 0;
                    if (i == k) {
                        leftMax = 0;
                    } else {
                        leftMax = findMax(arr, i, k);
                    }

                    int rightMax = 0;
                    if (k + 1 == j) {
