import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public int[] smallestSufficientTeam(String[] skills, List<List<String>> people) {
        int n = skills.length;
        int m = people.size();

        // Create a map from skill to its index
        Map<String, Integer> skillIndexMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            skillIndexMap.put(skills[i], i);
        }

        // Create a bitmask for each person representing the skills they have
        int[] masks = new int[m];
        for (int i = 0; i < m; i++) {
            for (String skill : people.get(i)) {
                masks[i] |= (1 << skillIndexMap.get(skill));
            }
        }

        // dp[i] represents the minimum number of people needed to cover the skills represented by the bitmask i
        int[] dp = new int[1 << n];
        for (int i = 1; i < (1 << n); i++) {
            dp[i] = Integer.MAX_VALUE;
        }

        // team[i] stores the index of the last person added to the team to cover the skills represented by the bitmask i
        int[] team = new int[1 << n];

        // Iterate over all possible bitmasks
        for (int mask = 0; mask < (1 << n); mask++) {
            // If the mask is not possible, skip it
            if (dp[mask] == Integer.MAX_VALUE) {
                continue;
            }

            // Iterate over all people
            for (int i = 0; i < m; i++) {
                // Calculate the new mask by combining the current mask with the skills of the current person
                int newMask = mask | masks[i];

                // If the new mask has not been visited or the number of people needed to cover the new mask is less than the current minimum, update the minimum and the team
                if (dp[newMask] > dp[mask] + 1) {
                    dp[newMask] = dp[mask] + 1;
                    team[newMask] = i;
                }
            }
        }

        // Reconstruct the team from the team array
        List<Integer> result = new ArrayList<>();
        int finalMask = (1 << n) - 1;
        int currentMask = finalMask;
        while (currentMask > 0) {
            int personIndex = team[currentMask];
            result.add(personIndex);
            currentMask &= ~ (1 << personIndex);
        }

        // Convert the result to an array
        int[] resultArray = new int[result.size()];
        for (int i = 0; i < result.size(); i++) {
            resultArray[i] = result.get(i);
        }

        return resultArray;
    }
}

