import java.util.HashMap;

public class Solution {
    public int longestWPI(int[] hours) {
        int n = hours.length;
        int[] score = new int[n];
        for (int i = 0; i < n; i++) {
            score[i] = hours[i] - 8;
        }

        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + score[i];
        }

        int maxLen = 0;
        HashMap<Integer, Integer> map = new HashMap<>();
        for (int i = 0; i <= n; i++) {
            if (!map.containsKey(prefixSum[i])) {
                map.put(prefixSum[i], i);
            }
            if (prefixSum[i] < 0) {
                maxLen = Math.max(maxLen, i - map.get(0));
            } else {
                int floor = -1;
                for (int key : map.keySet()) {
                    if (key <= prefixSum[i]) {
                        floor = Math.max(floor, key);
                    }
                }
                if (floor != -1) {
                    maxLen = Math.max(maxLen, i - map.get(floor));
                }
            }
        }

        return maxLen;
    }
}

