        int[] score = new int[n];
        for (int i = 0; i < n; i++) {
            score[i] = hours[i] > 8 ? 1 : -1;
        }

        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + score[i];
        }

        int maxLen = 0;
        HashMap<Integer, Integer> seen = new HashMap<>();
        for (int i = 0; i <= n; i++) {
            if (!seen.containsKey(prefixSum[i])) {
                seen.put(prefixSum[i], i);
            }
            if (prefixSum[i] < 0) {
                if (seen.containsKey(-prefixSum[i])) {
                    maxLen = Math.max(maxLen, i - seen.get(-prefixSum[i]));
                }
            } else {
                if (seen.containsKey(prefixSum[i])) {
                    maxLen = Math.max(maxLen, i - seen.get(prefixSum[i]));
                }
            }
        }

        return maxLen;
    }
}

