import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    /**
     * Given an array of strings transaction where transactions[i] consists of comma-separated values
     * representing the name, time (in minutes), amount, and city of the transaction.
     * Return a list of transactions that are possibly invalid.
     * You may return the answer in any order.
     *
     * @param transactions An array of strings representing transactions.
     * @return A list of transactions that are possibly invalid.
     */
    public List<String> findInvalidTransactions(List<String> transactions) {
        List<String> invalidTransactions = new ArrayList<>();
        List<Transaction> transactionObjects = new ArrayList<>();

        // Parse transactions into Transaction objects
        for (String transaction : transactions) {
            String[] parts = transaction.split(",");
            String name = parts[0];
            int time = Integer.parseInt(parts[1]);
            int amount = Integer.parseInt(parts[2]);
            String city = parts[3];
            transactionObjects.add(new Transaction(name, time, amount, city));
        }

        // Check for invalid transactions
        for (int i = 0; i < transactionObjects.size(); i++) {
            Transaction currentTransaction = transactionObjects.get(i);

            // Check if amount exceeds $1000
            if (currentTransaction.amount > 1000) {
                invalidTransactions.add(currentTransaction.toString());
                continue;
            }

            // Check for transactions within 60 minutes of another transaction with the same name in a different city
            for (int j = 0; j < transactionObjects.size(); j++) {
                if (i != j && transactionObjects.get(j).name.equals(currentTransaction.name)
                        && !transactionObjects.get(j).city.equals(currentTransaction.city)
                        && Math.abs(transactionObjects.get(j).time - currentTransaction.time) <= 60) {
                    invalidTransactions.add(currentTransaction.toString());
                    break;
                }
            }
        }

        return invalidTransactions;
    }

    private static class Transaction {
        String name;
        int time;
        int amount;
        String city;

        public Transaction(String name, int time, int amount, String city) {
            this.name = name;
            this.time = time;
            this.amount = amount;
            this.city = city;
        }

        @Override
        public String toString() {
            return String.format("%s,%d,%d,%s", name, time, amount, city);
        }
    }
}

