import java.util.Map;

public class Solution {
    public List<String> findInvalidTransactions(List<String> transactions) {
        List<String> invalidTransactions = new ArrayList<>();
        Map<String, List<Transaction>> transactionsByNameCity = new HashMap<>();

        for (String transactionStr : transactions) {
            String[] parts = transactionStr.split(",");
            String name = parts[0];
            int time = Integer.parseInt(parts[1]);
            double amount = Double.parseDouble(parts[2]);
            String city = parts[3];

            Transaction transaction = new Transaction(name, time, amount, city);

            if (amount > 1000) {
                invalidTransactions.add(transactionStr);
            } else {
                transactionsByNameCity.computeIfAbsent(name, k -> new ArrayList<>()).add(transaction);
            }
        }

        for (List<Transaction> transactions : transactionsByNameCity.values()) {
            for (int i = 0; i < transactions.size(); i++) {
                for (int j = i + 1; j < transactions.size(); j++) {
                    Transaction t1 = transactions.get(i);
                    Transaction t2 = transactions.get(j);

                    if (!t1.city.equals(t2.city) && Math.abs(t1.time - t2.time) <= 60) {
                        invalidTransactions.add(transactions.get(i).getTransactionString());
                        invalidTransactions.add(transactions.get(j).getTransactionString());
                    }
                }
            }
        }

        return invalidTransactions;
    }

    private static class Transaction {
        String name;
        int time;
        double amount;
        String city;

        public Transaction(String name, int time, double amount, String city) {
            this.name = name;
            this.time = time;
            this.amount = amount;
            this.city = city;
        }

        public String getTransactionString() {
            return name + "," + time + "," + amount + "," + city;
        }
    }
}

