import java.util.LinkedList;
import java.util.List;

public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        List<Integer> path = new LinkedList<>();
        int row = 0;
        int temp = label;
        while (temp > 0) {
            row++;
            temp /= 2;
        }

        path.add(1);
        int current = 1;
        for (int i = 1; i < row; i++) {
            if (i % 2 == 1) {
                current = 2 * current - 1;
            } else {
                current = 2 * current;
            }
            path.add(current);
        }

        int last = label;
        for (int i = row - 1; i >= 0; i--) {
            if (i % 2 == 1) {
                last = 2 * last + 1 - (int)Math.pow(2, i);
            } else {
                last = 2 * last - (int)Math.pow(2, i);
            }
            if(i == 0) break;
            path.add(0, last);
        }

        return path;
    }
}

