import java.util.LinkedList;
import java.util.List;

public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        List<Integer> path = new LinkedList<>();
        int row = 1;
        int totalNodes = 0;

        while (label > 0) {
            path.add(0, label);
            totalNodes = (int) Math.pow(2, row) - 1;
            if (label <= totalNodes) {
                break;
            }
            label -= totalNodes;
            row++;
        }

        if (row > 1) {
            int current = label;
            for (int i = row - 2; i >= 0; i--) {
                int nodesInRow = (int) Math.pow(2, i + 1) - 1;
                current = nodesInRow - current + 1;
                path.add(0, current);
            }
        }

        return path;
    }
}

