        while (totalNodes < label) {
            totalNodes += Math.pow(2, row);
            row++;
        }

        int currentLabel = label;
        path.add(label);

        while (row > 0) {
            int nodesInPreviousRow = (int) Math.pow(2, row - 1);
            int position = (int) Math.ceil((double) currentLabel / (Math.pow(2, row)));

            if (row % 2 == 0) {
                currentLabel = (int) (nodesInPreviousRow - (currentLabel - nodesInPreviousRow) + 1);
            } else {
                currentLabel = (int) (nodesInPreviousRow - (currentLabel - nodesInPreviousRow));
            }

            path.add(currentLabel);
            row--;
        }

        return path;
    }
}

