        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '(') {
                stack.push(i);
            } else if (s.charAt(i) == ')') {
                int start = stack.pop();
                pairs[start] = i;
                pairs[i] = start;
            }
        }

        StringBuilder sb = new StringBuilder();
        int dir = 1;
        int i = 0;
        while (i < n) {
            if (s.charAt(i) == '(' || s.charAt(i) == ')') {
                i = pairs[i];
                dir = -dir;
            } else {
                sb.append(s.charAt(i));
            }
            i += dir;
        }

        return sb.toString();
    }
