import java.util.HashMap;
import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public String alphabetBoardPath(String target) {
        HashMap<Character, int[]> map = new HashMap<>();
        int[] board = {'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z'};
        for (int i = 0; i < board.length; i++) {
            map.put((char) (board[i] + 'a'), new int[]{i / 5, i % 5});
        }

        int[] curr = {0, 0};
        StringBuilder path = new StringBuilder();

        for (char c : target.toCharArray()) {
            int[] next = map.get(c);

            while (curr[0] > next[0]) {
                path.append('U');
                curr[0]--;
            }
            while (curr[1] > next[1]) {
                path.append('L');
                curr[1]--;
            }
            while (curr[0] < next[0]) {
                path.append('D');
                curr[0]++;
            }
            while (curr[1] < next[1]) {
                path.append('R');
                curr[1]++;
            }
            path.append('!');
            curr = next;
        }

        return path.toString();
    }
}

