public class Solution {
    public int[] distributeCandies(int candies, int numPeople) {
        int[] result = new int[numPeople];
        int currentCandy = 1;
        int personIndex = 0;

        while (candies > 0) {
            int give = Math.min(candies, currentCandy);
            result[personIndex] += give;
            candies -= give;
            personIndex = (personIndex + 1) % numPeople;
            currentCandy++;
        }

        return result;
    }
}

