// #Medium #String #Stack #2023_06_01_Time_1_ms_(100.00%)_Space_43.8_MB_(23.00%)
public class Solution {
    public int[] maxDepthAfterSplit(String seq) {
        int n = seq.length();
        int[] ans = new int[n];
        Stack<Integer> stack = new Stack<>();
        int depth = 0;
        for (int i = 0; i < n; i++) {
            if (seq.charAt(i) == '(') {
                stack.push(depth);
                depth++;
                ans[i] = 0;
            } else {
                ans[i] = 1;
                depth = stack.pop() + 1;
            }
        }
        return ans;
    }
}

