public class Solution {
    public int minNonZeroProduct(int p) {
        long mod = 1000000007;
        if (p == 1) {
            return 1;
        }

        long product = 1;
        for (int i = 1; i < p; i++) {
            product = (product * i) % mod;
        }

        if (product == 0) {
            return 0;
        }

        return (int) product;
    }
}

