public class Solution {
    public int minNonZeroProduct(int p) {
        long product = 1;
        for (int i = 1; i < (1 << p); i++) {
            product = (product * i) % 1000000007;
        }

        long minProduct = Long.MAX_VALUE;
        for (int i = 1; i < (1 << p); i++) {
            long currentProduct = 1;
            for (int j = 1; j < (1 << p); j++) {
                if ((i & j) != 0) {
                    currentProduct = (currentProduct * j) % 1000000007;
                }
            }
            if (currentProduct != 0) {
                minProduct = Math.min(minProduct, currentProduct);
            }
        }

        if (minProduct == Long.MAX_VALUE) {
            return 1;
        }

        return (int) minProduct;
    }
}

