import java.util.Arrays;

public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        int[] ans = new int[n];
        Arrays.sort(sums);

        if (n == 2) {
            ans[0] = sums[0];
            ans[1] = sums[1] - sums[0];
            return ans;
        }

        ans[0] = sums[0];
        for (int i = 1; i < n; i++) {
            ans[i] = sums[i] - sums[0];
        }

        if (isValid(n, sums, ans)) {
            return ans;
        }

        ans[0] = sums[1];
        for (int i = 1; i < n; i++) {
            ans[i] = sums[i] - sums[0];
        }

        if (isValid(n, sums, ans)) {
            return ans;
        }

        return ans;
    }

    private boolean isValid(int n, int[] sums, int[] arr) {
        boolean[] found = new boolean[sums.length];
        generateSubsetSums(arr, 0, 0, found, sums);
        for (boolean b : found) {
            if (!b) {
                return false;
            }
        }
        return true;
    }

    private void generateSubsetSums(int[] arr, int index, int currentSum, boolean[] found, int[] sums) {
        if (index == arr.length) {
            for (int i = 0; i < sums.length; i++) {
                if (sums[i] == currentSum) {
                    found[i] = true;
                    return;
                }
            }
            return;
        }

        generateSubsetSums(arr, index + 1, currentSum + arr[index], found, sums);
        generateSubsetSums(arr, index + 1, currentSum, found, sums);
    }
