import java.util.Arrays;

public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        int[] ans = new int[n];
        Arrays.sort(sums);

        if (n == 1) {
            ans[0] = sums[0];
            return ans;
        }

        ans[0] = sums[0];

        for (int i = 1; i < n; i++) {
            ans[i] = sums[i] - sums[0];
        }

        if (n == 2) {
            return ans;
        }

        int[] currentSums = new int[1 << n];
        for (int i = 0; i < (1 << n); i++) {
            int sum = 0;
            for (int j = 0; j < n; j++) {
                if ((i >> j) % 2 == 1) {
                    sum += ans[j];
                }
            }
            currentSums[i] = sum;
        }

        boolean valid = true;
        for(int sum : sums){
            boolean found = false;
            for(int i = 0; i < (1 << n); i++){
                if(currentSums[i] == sum){
                    found = true;
                    break;
                }
            }
            if(!found){
                valid = false;
                break;
            }
        }

        if(!valid){
            ans[0] = sums[1];
            for (int i = 1; i < n; i++) {
                ans[i] = sums[i+1] - sums[0];
            }
        }


        return ans;
    }
}

