public class Solution {
    public int eliminateMaximum(int[] dist, int[] speed) {
        int n = dist.length;
        double[] timeToReachCity = new double[n];
        for (int i = 0; i < n; i++) {
            timeToReachCity[i] = (double) dist[i] / speed[i];
        }

        PriorityQueue<Double> pq = new PriorityQueue<>();
        for (double time : timeToReachCity) {
            pq.offer(time);
        }

        int eliminatedMonsters = 0;
        int currentTime = 0;
        while (!pq.isEmpty()) {
            double time = pq.poll();
            if (time > currentTime) {
                eliminatedMonsters++;
                currentTime = currentTime + 1;
            } else {
                break;
            }
        }

        return eliminatedMonsters;
    }
}

