public class Solution {
    public long maxMatrixSum(int[][] matrix) {
        int n = matrix.length;
        long sum = 0;
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dp[i][j] = matrix[i][j];
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i > 0) {
                    dp[i][j] = Math.max(dp[i][j], dp[i - 1][j] + matrix[i][j]);
                }
                if (j > 0) {
                    dp[i][j] = Math.max(dp[i][j], dp[i][j - 1] + matrix[i][j]);
                }
                if (i < n - 1) {
                    dp[i][j] = Math.max(dp[i][j], dp[i + 1][j] + matrix[i][j]);
                }
                if (j < n - 1) {
                    dp[i][j] = Math.max(dp[i][j], dp[i][j + 1] + matrix[i][j]);
                }
            }
        }

        long max_sum = dp[0][0];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                max_sum = Math.max(max_sum, dp[i][j]);
            }
        }

        return max_sum;
    }
}

