public class Solution {
    public int[][] rotateGrid(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        k = k % (m * n);

        for (int layer = 0; layer < m / 2; layer++) {
            for (int rotation = 0; rotation < k; rotation++) {
                int[] temp = new int[m * n];
                int index = 0;

                // Copy elements from the layer to a temporary array
                for (int i = layer; i < m - layer - 1; i++) {
                    for (int j = layer; j < n - layer - 1; j++) {
                        temp[index++] = grid[i][j];
                    }
                }

                index = 0;
                // Extract elements from the layer in counter-clockwise order
                int[] layerElements = new int[m * n];
                for (int i = layer; i < m - layer - 1; i++) {
                    for (int j = layer; j < n - layer - 1; j++) {
                        layerElements[index++] = grid[i][j];
                    }
                }

                index = 0;
                int layerSize = (m - 2 * layer) * (n - 2 * layer);
                int[] rotatedLayer = new int[layerSize];
                for (int i = 0; i < layerSize; i++) {
                    rotatedLayer[i] = layerElements[(i + (layerSize - 1)) % layerSize];
                }

                index = 0;
                for (int i = layer; i < m - layer - 1; i++) {
                    for (int j = layer; j < n - layer - 1; j++) {
                        grid[i][j] = rotatedLayer[index++];
                    }
                }
            }
        }

        return grid;
    }
}

