public class Solution {
    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        int n = students.length;
        int[] assignment = new int[n];
        Arrays.fill(assignment, -1);
        int maxScore = 0;

        for (int i = 0; i < (1 << n); i++) {
            boolean valid = true;
            int[] mentorUsed = new int[n];
            Arrays.fill(mentorUsed, 0);

            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) != 0) {
                    if (mentorUsed[j] == 1) {
                        valid = false;
                        break;
                    }
                    mentorUsed[j] = 1;
                }
            }

            if (!valid) continue;

            int currentScore = 0;
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) != 0) {
                    currentScore += calculateCompatibility(students[j], mentors[j]);
                }
            }
            maxScore = Math.max(maxScore, currentScore);
        }

        return maxScore;
    }

    private int calculateCompatibility(int[] studentAnswers, int[] mentorAnswers) {
        int score = 0;
        for (int i = 0; i < studentAnswers.length; i++) {
            if (studentAnswers[i] == mentorAnswers[i]) {
                score++;
            }
        }
        return score;
    }
}

